INSERT INTO `bericht` (`id`, `body`, `created_on`) VALUES
(3, 'Het is nu mogelijk om de speeltuinen op de kaart te filteren! Klik op het Filter-knopje, (op grote schermen) links van of (op mobiele devices) bovenaan de kaart, om te bepalen welke speeltuinen je wilt zien: alleen kinderboerderijen, alle speeltuinen die leuk zijn voor de allerkleinsten, alle speeltuinen met minstens een glijbaan etc. etc.', '2017-09-24 21:55:00'),
(4, 'Je kunt nu, bij beperkt toegankelijke speeltuinen, openingstijden en/of een kleine (vrijwillige) bijdrage opgeven.', '2017-10-17 21:07:59'),
(7, 'Geweldig! In korte tijd meer dan 80 speeltuinen erbij. Ga zo door! Zo maken we samen Speeltuinzoeker tot dÃ© plek om leuke speelplekken met elkaar te delen.', '2018-03-28 17:49:18');

