--
-- Tabelstructuur voor tabel `review`
--

CREATE TABLE `review` (
  `id` int(10) NOT NULL,
  `speeltuin_id` int(10) NOT NULL,
  `rating` int(2) NOT NULL,
  `comment` text NOT NULL,
  `user_id` int(10) NOT NULL,
  `status` tinyint(4) NOT NULL,
  `rated_on` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

--
-- Gegevens worden geëxporteerd voor tabel `review`
--

INSERT INTO `review` (`id`, `speeltuin_id`, `rating`, `comment`, `user_id`, `status`, `rated_on`) VALUES
(1, 3, 4, 'Mooie nieuwe speeltuin. Nog een wip o.i.d. erbij zou het helemaal afmaken.', 5, 1, '2017-10-13 22:37:07'),
(2, 138, 4, 'Mooi bos, maar weinig speelvoorzieningen. Parkeren bij de flat aan de Kerspellaan. Staat verder niet echt aangegeven.', 5, 1, '2017-10-25 17:55:58'),
(3, 15, 2, 'Vanwege de verbouwing van de school zijn momenteel alleen het voetbalveld en het speelhuisje met glijbaan toegankelijk.', 5, 1, '2018-02-12 08:13:08');

-- --------------------------------------------------------

--
-- Tabelstructuur voor tabel `speeltuin`
--

CREATE TABLE `speeltuin` (
  `id` int(11) NOT NULL,
  `naam` varchar(255) NOT NULL,
  `link` varchar(255) NOT NULL,
  `omschrijving` text NOT NULL,
  `locatie_omschrijving` text NOT NULL,
  `lat` float NOT NULL,
  `lon` float NOT NULL,
  `status_id` int(11) NOT NULL,
  `author_id` int(11) NOT NULL,
  `public` int(3) NOT NULL DEFAULT 1,
  `agecat_1` tinyint(1) NOT NULL DEFAULT 0,
  `agecat_2` tinyint(1) NOT NULL DEFAULT 1,
  `agecat_3` tinyint(1) NOT NULL DEFAULT 1,
  `speeltuintype` enum('Toestelspeeltuin','Natuurspeeltuin','Kinderboerderij','Kinderboerderij met speeltuin','Sportfaciliteit') NOT NULL DEFAULT 'Toestelspeeltuin',
  `seo_url` varchar(255) NOT NULL,
  `modified_on` datetime NOT NULL DEFAULT current_timestamp(),
  `total_rating` int(10) NOT NULL,
  `times_rated` int(10) NOT NULL,
  `avg_rating` float NOT NULL,
  `openingstijden` text NOT NULL,
  `vergoeding` text NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

--
-- Gegevens worden geëxporteerd voor tabel `speeltuin`
--

INSERT INTO `speeltuin` (`id`, `naam`, `link`, `omschrijving`, `locatie_omschrijving`, `lat`, `lon`, `status_id`, `author_id`, `public`, `agecat_1`, `agecat_2`, `agecat_3`, `speeltuintype`, `seo_url`, `modified_on`, `total_rating`, `times_rated`, `avg_rating`, `openingstijden`, `vergoeding`) VALUES
(1, 'Admiraal de Ruyterlaan', '', 'Mooie, grote speeltuin. Handig als je met de auto komt: parkeren kan op de naastgelegen parkeerstrook.', 'Admiraal de Ruyterlaan, Groningen', 53.211, 6.54773, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'admiraal-de-ruyterlaan', '2017-08-12 23:25:18', 0, 0, 0, '', ''),
(2, 'Weener', '', 'Kleine speeltuin, ideaal gelegen aan de weg waarop je het dorp binnenrijdt (vanuit de richting Leer). Ruime parkeergelegenheid.', 'Norderstrasse, Weener', 53.1706, 7.35937, 1, 5, 1, 0, 1, 0, 'Toestelspeeltuin', 'weener', '2017-08-12 23:25:18', 0, 0, 0, '', ''),
(3, 'Fazantweg', '', 'Net nieuwe speeltuin. Gezellig en met een groot grasveld eromheen.', 'Fazantweg, Paterswolde', 53.1453, 6.5589, 1, 5, 1, 1, 1, 1, 'Toestelspeeltuin', 'fazantweg', '2017-08-12 23:25:18', 4, 1, 4, '', ''),
(4, 'Stofakkers', '', 'Leuk buurtspeeltuintje, beetje verscholen in een woonwijk', 'Stofakkers, Ruinen', 52.766, 6.35783, 1, 5, 1, 1, 1, 1, 'Toestelspeeltuin', 'stofakkers', '2017-08-12 23:25:18', 0, 0, 0, '', ''),
(5, 'Reitdiephaven', '', 'Veilig omheind speeltuintje aan de haven', 'Reitdiephaven', 53.2355, 6.52636, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'reitdiephaven', '2017-08-12 23:25:18', 0, 0, 0, '', ''),
(6, 'Aquamarijnpad', '', 'Klein speeltuintje prachtig gelegen aan de rand van de stad', 'Aquamarijnpad', 53.2308, 6.51604, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'aquamarijnpad', '2017-08-12 23:25:18', 0, 0, 0, '', ''),
(7, 'Buurtspeeltuin Professorenbuurt', '', 'Grote speeltuin, veel te doen, veilig omgeven door een heg, op een rustige plek middenin de Professorenbuurt.', 'Tellegenstraat, Groningen', 53.2296, 6.57106, 1, 5, 1, 1, 1, 1, 'Toestelspeeltuin', 'buurtspeeltuin-professorenbuurt', '2017-08-12 23:25:18', 0, 0, 0, '', ''),
(8, 'Neerwoldeiland', '', 'Een van de vele leuke speeltuinen in Eelderwolde, met als grootste attractie de kabelbaan', 'Neerwoldeiland, Eelderwolde', 53.1759, 6.53833, 1, 5, 1, 1, 1, 1, 'Toestelspeeltuin', 'neerwoldeiland', '2017-08-12 23:25:18', 0, 0, 0, '', ''),
(9, 'Zweerdeneiland', '', 'Klein speeltuintje aan het water, veilig omheind. Leuke houten schommelboot.', 'Zweerdeneiland, Eelderwolde', 53.1766, 6.53758, 1, 5, 1, 1, 1, 1, 'Toestelspeeltuin', 'zweerdeneiland', '2017-08-12 23:25:18', 0, 0, 0, '', ''),
(10, 'De Onlanderij', '', 'Bij deze leuke en leerzame kijkboerderij bevindt zich een soort grote zandbak waar kinderen heerlijk met water en zand kunnen spelen', 'Madijk, Eelderwolde', 53.1778, 6.53408, 1, 5, 2, 1, 1, 1, 'Natuurspeeltuin', 'de-onlanderij', '2017-08-13 00:41:20', 0, 0, 0, '', ''),
(11, 'Buurtspeeltuin Kallandspad', '', 'Gezellige buurtspeeltuin waar heel veel te doen is', 'Kallandspad, Midsland Terschelling', 53.3837, 5.2832, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'buurtspeeltuin-kallandspad', '2017-08-19 23:40:46', 0, 0, 0, '', ''),
(12, 'Jachthaven West Terschelling', '', 'Mooi groot klimtoestel, met groot grasveld erbij', 'Jachthaven West Terschelling', 53.3641, 5.22051, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'jachthaven-west-terschelling', '2017-08-25 12:16:58', 0, 0, 0, '', ''),
(13, 'Buurtspeeltuin Zeedistelstraat', '', 'Leuk omheind buurtspeeltuintje', 'Zeedistelstraat', 53.363, 5.21559, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'buurtspeeltuin-zeedistelstraat', '2017-08-25 12:28:42', 0, 0, 0, '', ''),
(14, 'Centrum Roden', '', 'Allemaal leuke klim- en speeltoestellen op het centrale plein van Roden', 'Albertsbaan, Roden', 53.1374, 6.43128, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'centrum-roden', '2017-08-30 14:19:55', 0, 0, 0, '', ''),
(15, 'Schoolplein Westerburcht (vh. De Ekkel)', '', 'Buiten schooltijden kun je op het niet-afgesloten gedeelte leuk spelen, voetballen en basketballen.', 'Jan Steenweg, Eelde', 53.1413, 6.5574, 1, 5, 2, 0, 1, 1, 'Toestelspeeltuin', 'schoolplein-westerburcht-vh-de-ekkel', '2017-08-31 14:29:04', 2, 1, 2, '', ''),
(16, 'Newtonplein', '', 'glijbaan, brandweerauto klimtoestel, zandbak, schommels, klimrots, boomstammen, Dunea drinkwaterkraantje, op woensdagmiddag worden er fietsjes en karren buiten gezet voor spelen onder toezicht van materiaal. ', 'Newtonplein, Den Haag', 52.0723, 4.2783, 1, 9, 1, 1, 1, 1, 'Toestelspeeltuin', 'newtonplein', '2017-09-07 16:15:52', 0, 0, 0, '', ''),
(17, 'Mient speeltuin', '', 'Recent vernieuwd, klimrek voor oudere kinderen, klimrek voor kleine kinderen, babyschommel, twee schommels, omheind (voet-)balveldje, twee wipkippen, draaimolen. ', 'Mient speeltuin nabij Kinderboerderij De Gagelhoeve', 52.0702, 4.26862, 1, 9, 1, 1, 1, 1, 'Toestelspeeltuin', 'mient-speeltuin', '2017-09-01 11:24:41', 0, 0, 0, '', ''),
(18, '\'t Speelduin', '', 'Grote omheinde speeltuin nabij strand en duinen. Grond is zand. Veel soorten klimrekken, familieschommel, gedeeltelijk natuurspeeltuin met grote boomstammen.', 'Wieringsestraat, Scheveningen', 52.0916, 4.25646, 1, 9, 1, 1, 1, 1, 'Toestelspeeltuin', 't-speelduin', '2017-09-07 16:16:11', 0, 0, 0, '', ''),
(19, 'Speeltuin de Wijert PC Hoofdlaan ', '', 'Achter buurtcentrum en consultatiebureau. Grote veilig speeltuin, omgeven door hekwerk. Ook erg geschikt voor kleine kinderen! ', 'PC Hooftlaan 1 groningen', 53.1959, 6.57445, 1, 8, 1, 0, 1, 1, 'Toestelspeeltuin', 'speeltuin-de-wijert-pc-hoofdlaan-', '2017-09-01 13:08:04', 0, 0, 0, '', ''),
(20, 'Groene slof', '', 'Deze speeltuin heeft een ruim basketbal/voetbalveld met hoog hek. Daarnaast is een kleinere speeltuin met klimrek, glijbaan, draaimolentje, evenwichtstouw, drie schommels. ', 'Loosduinseweg / fahrenheitstraat', 52.0691, 4.27732, 1, 9, 1, 0, 1, 1, 'Toestelspeeltuin', 'groene-slof', '2017-09-07 16:16:19', 0, 0, 0, '', ''),
(21, 'Speeltuin Middelveen', 'http://bsvmiddelveen.123website.nl/414140360', 'Mooie, ruim opgezette speeltuin van Buurt- en Speeltuinvereniging \'Middelveen\'. Naast de grote speeltuin (aan de Suuddal) staan er in de wijk nog 4 kleinere speeltuinen. Allemaal worden ze onderhouden door de vrijwilligers van de buurt- en speeltuinvereniging. Zij zorgen ervoor dat de kinderen veilig en met veel plezier in de speeltuinen kunnen spelen.', 'Suuddal, Zuidwolde (Dr.)', 52.666, 6.4253, 1, 10, 1, 1, 1, 1, 'Toestelspeeltuin', 'speeltuin-middelveen', '2017-09-02 14:20:38', 0, 0, 0, '', ''),
(22, 'Zuiderpark Sand Hall Boas House', '', 'Omheinde speeltuin met grote western-achtig klimrek met twee grote glijbanen. Nog een kleiner klimrek met een buis. ', 'Zuiderpark, Den Haag', 52.0533, 4.28334, 1, 9, 1, 0, 1, 1, 'Toestelspeeltuin', 'zuiderpark-sand-hall-boas-house', '2017-09-02 09:29:28', 0, 0, 0, '', ''),
(24, 'Kinderboerderij De Griftsteede', '', 'Bij Griftsteede kun je spelen in de speeltuin of knuffelen met de dieren op de kinderboerderij!\r\nGriftsteede is een bruisende plek in het hart van de stad! Midden in het Griftpark vind je Grifsteede waar jong en oud lekker komt ontspannen of spelen. Ontdek de kinderboerderij met de nieuwsgierige geiten, schapen, koeien en kleine huisdieren waar je lekker mee kunt knuffelen! Ook kun je erop los speuren tijdens de boerderijspeurtocht.\r\n\r\nDirect naast de kinderboerderij is een fantastisch speeltuin waar je kunt komen klauteren in de speeltoestellen en glijden van de glijbaan! Deze speeltuin is zowel leuk voor de wat jongere kinderen als de wat oudere.', 'Van Swindenstraat 129,3514 XR Utrecht', 52.1016, 5.12877, 1, 12, 2, 0, 1, 1, 'Kinderboerderij met speeltuin', 'kinderboerderij-de-griftsteede', '2017-09-02 12:35:25', 0, 0, 0, '', ''),
(25, 'Thea Beckmanpad', '', '', 'Van Hardenbroeklaan 38, 3981 EP Bunnik', 52.0689, 5.19899, 1, 12, 1, 0, 1, 1, 'Toestelspeeltuin', 'thea-beckmanpad', '2017-09-02 12:45:01', 0, 0, 0, '', ''),
(26, 'Zuiderpark natuurspeeltuin', '', 'Een prachtige natuurspeeltuin met ondiep riviertje met planken erover, kleine watervalletjes, grote rotsen, een lange betonnen buis, uitkijktoren en gras en picknicktafels. Tip: neem droge kleren mee en eventueel zwemkleding. ', 'Zuiderpark, Henriette Roland Holstweg, Den Haag', 52.0586, 4.28856, 1, 9, 1, 1, 1, 1, 'Natuurspeeltuin', 'zuiderpark-natuurspeeltuin', '2017-09-07 16:16:49', 0, 0, 0, '', ''),
(27, 'Zuiderpark speeltuin', '', 'Zeer grote speeltuin met klimkasteel, schommels, zandbak, klimpiramides van touwen van zo\'n 6 m hoog. Voor de allerkleinsten zijn er babyschommels maar weinig klimmogelijkheden of glijbanen voor kleintjes. ', 'Zuiderpark Henriette Roland Holstweg Den Haag', 52.0605, 4.28447, 1, 9, 1, 1, 1, 1, 'Toestelspeeltuin', 'zuiderpark-speeltuin', '2017-09-07 16:18:15', 0, 0, 0, '', ''),
(28, 'Speeltuin Kortenbos', '', 'Speeltuin met klimrek en glijbaan, houten palen met touwen en hangmatten, basketbalveld, groot grasveld met een labyrint van stenen, wipkippen en wipwappen, pingpongtafel. ', 'Kortenbos, nabij Westeinde', 52.0759, 4.29939, 1, 9, 1, 0, 1, 1, 'Toestelspeeltuin', 'speeltuin-kortenbos', '2017-09-07 16:18:31', 0, 0, 0, '', ''),
(29, 'Droppingsveld Groningen ', '', 'Kleine maar leuke speeltuin in de wijk Laanhuizen. Schommel, trampoline, twee wipkippen, klimrek met zandbak, speelhuisje met glijbaan, rekstokken en basketbalveld. Ook picknicktafel en diverse bankjes. Schoon en gezellig want vaak veel kinderen en ouders aanwezig. ', 'Droppingsveld, Groningen ', 53.2082, 6.55561, 1, 13, 1, 0, 1, 1, 'Toestelspeeltuin', 'droppingsveld-groningen-', '2017-09-03 13:25:06', 0, 0, 0, '', ''),
(30, 'Kosterspad', '', 'Buurtspeeltuintje met hangplek voor de wat oudere jeugd', 'Kosterspad, Zoeterwoude', 52.1202, 4.49725, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'kosterspad', '2017-09-03 13:30:28', 0, 0, 0, '', ''),
(31, 'Skatebaan rotonde Siersteenlaan', '', 'Ruime, omheinde skatebaan', 'Siersteenlaan, Groningen', 53.2221, 6.51384, 1, 5, 1, 0, 1, 1, 'Sportfaciliteit', 'skatebaan-rotonde-siersteenlaan', '2017-09-04 13:55:24', 0, 0, 0, '', ''),
(32, 'Beukplein', '', 'klein speeltuintje met een klimrek en leuke kromlopende buisglijbaan. ', '', 52.0783, 4.27367, 1, 9, 1, 0, 1, 1, 'Toestelspeeltuin', 'beukplein', '2017-09-07 16:18:38', 0, 0, 0, '', ''),
(33, 'Copernicuslaan Den Haag', '', 'Het is een langgerekt speelplein met een klimrek met brug, monkeybars en glijbaan. Er is een bielzenconstructie als evenwichtsbalk. Een nestschommel. En een klein voetbalveldje met laag metalen hek en doelen, speciaal voor kleine kinderen.', 'Copernicuslaan, Den Haag', 52.0746, 4.2715, 1, 9, 1, 1, 1, 1, 'Toestelspeeltuin', 'copernicuslaan-den-haag', '2017-09-07 16:19:35', 0, 0, 0, '', ''),
(34, 'Kinderboerderij de Gagelhoeve', 'https://www.denhaag.nl/nl/in-de-stad/vrije-tijd-en-recreatie/dieren-en-stadsboerderijen/stadsboerderij-de-gagelhoeve.htm', 'Deze kinderboerderij is erg leuk. Behalve de gebruikelijke boerderijdieren die je mag aaien en voeren, kun je ook helpen met vegen, op fietsjes rijden op een open betegeld stuk, er is een grote zandbak met waterpomp (die soms niet in gebruik is), allerlei boomstammen en van natuurlijke materialen gemaakte speelplekken. Er is ook een nestschommel en picknickbankjes etc. ', 'mient 210 den haag', 52.0697, 4.26634, 1, 9, 2, 0, 1, 1, 'Kinderboerderij met speeltuin', 'kinderboerderij-de-gagelhoeve', '2017-09-08 10:04:20', 0, 0, 0, '', ''),
(35, 'Hans Lodeizenstraat (de Held)', '', 'Buurtspeeltuin met mooie, nieuwe toestellen', 'Hans Lodeizenstraat, Groningen', 53.2235, 6.51313, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'hans-lodeizenstraat-de-held', '2017-09-04 13:38:07', 0, 0, 0, '', ''),
(36, 'Niek Engelschmanstraat (de Held)', '', 'Buurtspeeltuin met grasveld eromheen', 'Niek Engelschmanstraat, Groningen', 53.2257, 6.51311, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'niek-engelschmanstraat-de-held', '2017-09-04 13:40:00', 0, 0, 0, '', ''),
(37, 'Speeltuin Aquamarijnpad / Oscar Wildestraat', '', 'Aan de stadsrand gelegen speeltuin met veel (behendigheids)toestellen. Ernaast ligt een voetbalkooi.', 'Oscar Wildestraat, Groningen', 53.2309, 6.51364, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'speeltuin-aquamarijnpad--oscar-wildestraat', '2017-09-04 13:42:12', 0, 0, 0, '', ''),
(38, 'Kinderboerderij Pluk', 'http://plukdenhaag.nl/', 'Deze leuke kinderboerderij heeft behalve allerlei dieren (waaronder ook varkentjes) ook een lunchroom met veel biologische producten en met een terras. Naast het terras is een ruime zandbak met waterelement. Er is een mooi wandelgebied naast de kinderboerderij en er worden regelmatig leuke evenementen georganiseerd, zoals het lentefeest (een verhaal wordt bij een kampvuur verteld, je kunt knutselen, een speurtocht doen). \r\nJe kunt hier ook een kinderfeestje geven. ', '', 52.0504, 4.2286, 1, 9, 2, 0, 1, 1, 'Kinderboerderij', 'kinderboerderij-pluk', '2017-09-07 16:20:21', 0, 0, 0, '', ''),
(39, 'Voetbalkooi Aquamarijnpad / Oscar Wildestraat', '', 'Lekker voetballen in deze mooie voetbalkooi.', 'Oscar Wildestraat, Groningen', 53.2311, 6.51409, 1, 5, 1, 0, 1, 1, 'Sportfaciliteit', 'voetbalkooi-aquamarijnpad--oscar-wildestraat', '2017-09-04 13:43:37', 0, 0, 0, '', ''),
(40, 'Briljantstraat (Vinkhuizen)', '', 'Leuk beschut speeltuintje met fantastisch groot (voetbal)veld ernaast.', 'Briljantstraat, Groningen', 53.2309, 6.52106, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'briljantstraat-vinkhuizen', '2017-09-04 13:46:02', 0, 0, 0, '', ''),
(41, 'Geitenboerderij \'t Geertje', 'https://hetgeertje.nl/', 'Grote, ontzettend leuke geitenboerderij met vele faciliteiten: kleine geitjes de fles geven, iets gebruiken in de brasserie, iets kopen in de winkel (lokaal gemaakt), pony rijden, in de speeltuin spelen, andere dieren bekijken (o.a. koeien, varkens, kippen). De toegang is gratis, maar het wordt op prijs gesteld als bezoekers iets gebruiken in de brasserie of winkel. ', 'Geerweg 7, Zoeterwoude', 52.0944, 4.50536, 1, 9, 2, 0, 1, 1, 'Kinderboerderij', 'geitenboerderij-t-geertje', '2017-09-07 16:20:28', 0, 0, 0, '', ''),
(42, 'Kinderboerderij Herweijerhoeve Den Haag', 'https://www.denhaag.nl/nl/in-de-stad/vrije-tijd-en-recreatie/dieren-en-stadsboerderijen/stadsboerderij-de-herweijerhoeve-escamp.htm', 'Deze kinderboerderij heeft allerlei leuke dieren binnen en buiten om te borstelen, aaien en knuffelen. Er zijn ook wat spelletjes rondom de boerderij te doen (een nepkoe melken bijvoorbeeld). ', 'Anna Polakweg 7, Zuiderpark, Den Haag', 52.0587, 4.27957, 1, 9, 2, 0, 1, 1, 'Kinderboerderij', 'kinderboerderij-herweijerhoeve-den-haag', '2017-09-07 16:20:34', 0, 0, 0, '', ''),
(43, 'Recreatieplas Hoogkerk', '', 'Bij de plas bevinden zich bankjes en een paar speeltoestellen.', '', 53.2074, 6.51373, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'recreatieplas-hoogkerk', '2017-09-05 09:15:15', 0, 0, 0, '', ''),
(44, 'Blauwe Druifjespad', '', 'Deze speeltuin is ruim en goed gesorteerd. Kabelbaan, groot klimrek, twee schommels, familieschommel, nestschommel, zandbak, wip, draaimolen klein en draaimolen groot, twee speelhuisjes en een tennisveld met tussenschot met gaten waar je een bal door kunt schoppen. Ook voor hele kleine kinderen is er een speelhuisje en miniglijbaantje. ', 'Blauwe druifjespad, Den Haag', 52.0774, 4.25998, 1, 9, 1, 1, 1, 1, 'Toestelspeeltuin', 'blauwe-druifjespad', '2017-09-07 16:21:12', 0, 0, 0, '', ''),
(45, 'Monkeybos Meijendel', 'https://www.dunea.nl/bezoekerscentrum/monkeybos', 'Dit is een natuurspeeltuin met klimbomen, grote waterleidingbuizen om doorheen te kruipen, touwen om in de klimmen en zwaaien, kabelbaan. Gelegen in een natuurgebied met brasserie nabij met leuk waterelement waar kinderen kunnen spelen. Zie website. ', 'Meijendel', 52.1309, 4.33839, 1, 9, 2, 0, 1, 1, 'Natuurspeeltuin', 'monkeybos-meijendel', '2017-09-07 16:21:21', 0, 0, 0, '', ''),
(47, 'Warmoltseiland', '', 'De grote wipkrokodil is het meest opvallende toestel in deze ruim opgezette speeltuin.', 'Warmoltseiland, Eelderwolde', 53.1736, 6.54039, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'warmoltseiland', '2017-09-07 08:39:10', 0, 0, 0, '', ''),
(48, 'Oosterpark', '', '', 'Hortensialaan, groningen', 53.224, 6.58883, 1, 10, 1, 0, 1, 0, 'Toestelspeeltuin', 'oosterpark', '2017-09-07 12:25:54', 0, 0, 0, '', ''),
(50, 'Nieuwe Akkers', '', 'Recent aangelegde buurtspeeltuin waar veel te doen is.', 'Parmentierweg, Paterswolde', 53.1477, 6.56164, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'nieuwe-akkers', '2017-09-10 11:27:32', 0, 0, 0, '', ''),
(51, 'Fluitekruid', '', 'Klein buurtspeeltuintje', 'Fluitekruid, Eelde', 53.1436, 6.55204, 1, 5, 1, 0, 1, 0, 'Toestelspeeltuin', 'fluitekruid', '2017-09-10 11:54:27', 0, 0, 0, '', ''),
(52, 'Kijkboerderij \'t Hoogeveld', '', 'Koetjes en kalfjes kijken in de kijkstal, en daarnaast lekker met zand en water spelen', 'Helmerdijk, Eelde', 53.1415, 6.54503, 1, 5, 1, 0, 1, 1, 'Natuurspeeltuin', 'kijkboerderij-t-hoogeveld', '2017-09-10 12:20:22', 0, 0, 0, '', ''),
(53, 'Reitdiephaven/Hoogeweg', '', 'Klimtoestel met glijbaan, afgesloten door een hek. Direct naast de ingang van de haven. ', '', 53.2374, 6.52513, 1, 15, 1, 1, 1, 1, 'Toestelspeeltuin', 'reitdiephavenhoogeweg', '2017-09-10 14:12:37', 0, 0, 0, '', ''),
(54, 'De Droge Driehoek', '', '', '', 52.477, 6.06405, 1, 18, 1, 1, 1, 0, 'Toestelspeeltuin', 'de-droge-driehoek', '2017-09-12 14:50:59', 0, 0, 0, '', ''),
(55, 'Bosjes van Pex', '', 'Deze grote speeltuin heeft een zandbodem, is omgeven door bos en heeft praktisch alle soorten klim- en klautermogelijkheden. Ernaast ligt een groot grasveld voor voetballen. En nabij is een brasserie waar je ook naar de wc kunt. ', '', 52.072, 4.24664, 1, 9, 1, 1, 1, 1, 'Toestelspeeltuin', 'bosjes-van-pex', '2017-09-13 06:45:51', 0, 0, 0, '', ''),
(56, 'Waterleidingduinen', '', 'Deze speeltuin bevindt zich naast brasserie de Oase aan de ingang van de waterleidingduinen. Uiteraard ga je eerst wandelen in de duinen, hertjes kijken en zo. Als je weer teruggaat naar de parkeerplaats kom je langs deze speeltuin, beetje oud, maar onze kinderen vonden de oude (echte!) trekker heel leuk om in te klimmen. \r\nBij de Oase verkopen ze de lekkerste pannenkoeken. Er staat wel een hoge heg tussen terras en speeltuin dus je hebt geen zicht op de kinderen terwijl je daar zit. ', '', 52.3461, 4.58283, 1, 9, 1, 0, 1, 1, 'Toestelspeeltuin', 'waterleidingduinen', '2017-09-13 06:55:38', 0, 0, 0, '', ''),
(57, 'Groote Veen', '', 'Kabelbaan en boomstammen om lekker op te klauteren', 'De Voorakker, Eelde', 53.1359, 6.57502, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'groote-veen', '2017-09-13 21:46:47', 0, 0, 0, '', ''),
(58, 'Beatrixweg Appingedam', '', 'Ruime speeltuin aan t eind van een doodlopende straat. Omheind met een heg.', 'Beatrixweg Appingedam', 53.3251, 6.86673, 1, 11, 1, 1, 1, 1, 'Toestelspeeltuin', 'beatrixweg-appingedam', '2017-09-13 21:25:16', 0, 0, 0, '', ''),
