(67, 'Speeltuinvereniging Lage Weg (Prinsenhof)', '', 'Leuk speeltuintje met trapveldje en speeltoestellen (weet alleen niet meer exact welke toestellen allemaal). Ligt achter de huizen aan \'t Lage van de Weg.', '\'t Lage van de Weg', 53.4105, 6.65434, 1, 11, 1, 1, 1, 1, 'Toestelspeeltuin', 'speeltuinvereniging-lage-weg-prinsenhof', '2017-09-14 10:09:37', 0, 0, 0, '', ''),
