(75, 'Kinderboerderij de Hofstede', 'https://www.assen.nl/kinderboerderij-de-hofstede', 'Dierenweides, een vogeleiland, een speeltuintje en een mooi aangelegd park rondom de nieuwe vijver. Er is volop gelegenheid om dichtbij de dieren te komen. In de knuffelweide kun je verschillende landbouwhuisdieren aaien, zoals geiten, varkens en een ezel. In de knuffelhoek van de boerderij vind je de caviaâ€™s en konijnen.', 'Bosrand 1, Assen', 52.986, 6.54774, 1, 21, 2, 0, 1, 1, 'Kinderboerderij', 'kinderboerderij-de-hofstede', '2017-09-14 23:28:22', 0, 0, 0, '', ''),
(76, 'Solwerd', '', 'Kleine speeltuin met een klimrek en een voetbalveld, inclusief twee kleine doelen. ', 'Solwerd', 53.2455, 6.51683, 1, 15, 1, 0, 1, 1, 'Toestelspeeltuin', 'solwerd', '2017-09-15 16:30:45', 0, 0, 0, '', ''),
