(83, 'Speeltuin met kabelbaan aan de Bemweg / Sleeg, Zevenaar (nabij voetbalveld en buurtboomgaard)', '', 'Speeltuin met kabelbaan nabij voetbalveld en buurtboomgaard.\r\nParkeeradvies: Kindercentrum Groot Holthuizen, Bemlaan 1, 6905 VH Zevenaar.', 'Sleeg, Zevenaar', 51.9185, 6.09304, 1, 24, 1, 0, 1, 1, 'Toestelspeeltuin', 'speeltuin-met-kabelbaan-aan-de-bemweg--sleeg-zevenaar-nabij-voetbalveld-en-buurtboomgaard', '2017-09-17 10:06:01', 0, 0, 0, '', ''),
(84, 'Voetbalveld aan de Sleeg, Zevenaar (nabij speeltuin met kabelbaan en buurtboomgaard)', '', 'Voetbalveld nabij speeltuin met kabelbaan en buurtboomgaard.\r\nParkeeradvies: Kindercentrum Groot Holthuizen, Bemlaan 1, 6905 VH Zevenaar.\r\n', 'Sleeg, Zevenaar', 51.9186, 6.09424, 1, 24, 1, 0, 1, 1, 'Sportfaciliteit', 'voetbalveld-aan-de-sleeg-zevenaar-nabij-speeltuin-met-kabelbaan-en-buurtboomgaard', '2017-09-17 10:07:46', 0, 0, 0, '', ''),
(85, 'Kinderboerderij Rosorum, Zevenaar', 'http://www.kinderboerderijrosorum.nl/', 'Kinderboerderij gelegen in mooi park. Mogelijk meer voorzieningen aanwezig dan aangegeven.', 'Methen 2B, Zevenaar', 51.937, 6.06008, 1, 24, 2, 1, 1, 1, 'Kinderboerderij', 'kinderboerderij-rosorum-zevenaar', '2017-09-16 16:12:02', 0, 0, 0, '', ''),
(86, 'Speelbos Houwerzijl', '', 'Hutten bouwen, vissen in een sloot, spelen met een waterpomp en waterbaan. Een superspeeltuin!', 'Hoofdstraat Houwerzijl (naast de theefabriek)', 53.3364, 6.33902, 1, 25, 1, 1, 1, 1, 'Natuurspeeltuin', 'speelbos-houwerzijl', '2017-09-16 19:50:29', 0, 0, 0, '', ''),
(87, 'Parco Lungolago', '', 'In ItaliÃ«.\r\nParco Lungolago: Park met waterfonteinen,  zonneveld en voorziening, nabij strand aan Lago Maggiore. \r\nGeen entreekosten, maar wel betaald parkeren. ', 'Germignaga, ItaliÃ«', 45.9963, 8.72411, 1, 24, 1, 1, 1, 1, 'Toestelspeeltuin', 'parco-lungolago', '2017-09-21 13:58:24', 0, 0, 0, '', ''),
(88, 'Leuke buurtspeeltuin tussen de Tolsingel en de Bemsingel, Zevenaar', '', 'Leuke buurtspeeltuin.\r\nParkeeradvies: Tolsingel, Zevenaar. ', 'Tolsingel, Zevenaar ', 51.9192, 6.09806, 1, 24, 1, 1, 1, 0, 'Toestelspeeltuin', 'leuke-buurtspeeltuin-tussen-de-tolsingel-en-de-bemsingel-zevenaar', '2017-09-17 10:21:59', 0, 0, 0, '', ''),
(89, 'Basketbal- en voetbalveld (asfalt) bij Kinderdagverblijf De Toverhoed, Bemlaan 1, Zevenaar', '', 'Basketbal- en voetbalveldje op de parkeerplaats van Kinderdagverblijf De Toverhoed, Bemlaan 1, Zevenaar.\r\nErvaring leert dat de hekken naar de parkeerplaats open blijven. ', 'Bemlaan 1, Zevenaar ', 51.9196, 6.10152, 1, 24, 2, 0, 1, 1, 'Sportfaciliteit', 'basketbal--en-voetbalveld-asfalt-bij-kinderdagverblijf-de-toverhoed-bemlaan-1-zevenaar', '2017-09-17 10:33:10', 0, 0, 0, '', ''),
(90, 'Schoolplein van Basisschool De Bem, Zevenaar ', '', 'Schoolplein van Basisschool De Bem met voetbalveldje.\r\nTijdens schooltijden niet vrij toegankelijk, mogelijk buiten schooltijden ook niet altijd. ', 'Bemlaan 5, Zevenaar ', 51.9191, 6.10123, 1, 24, 2, 0, 1, 1, 'Toestelspeeltuin', 'schoolplein-van-basisschool-de-bem-zevenaar-', '2017-09-17 10:39:58', 0, 0, 0, '', ''),
(91, 'Klein buurtspeeltuintje met goal, Vierkantemorgenstraat, Zevenaar ', '', 'Klein buurtspeeltuintje voor de allerkleinsten en een  grasveldje met goal voor de wat oudere kids. Mogelijk van tijdelijke aard i.v.m. eventuele nieuwbouw. ', 'Vierkantemorgenstraat, Zevenaar ', 51.9199, 6.09569, 1, 24, 1, 1, 1, 1, 'Toestelspeeltuin', 'klein-buurtspeeltuintje-met-goal-vierkantemorgenstraat-zevenaar-', '2017-09-17 10:44:31', 0, 0, 0, '', ''),
(92, 'Rozemarijntuin', '', 'Een kleine glijbaan met huisje, veel gras en wat struiken. En een hinkelpad.', 'Rozemarijntuin, Assen', 53.0003, 6.50939, 1, 21, 1, 1, 1, 0, 'Toestelspeeltuin', 'rozemarijntuin', '2017-09-17 19:58:07', 0, 0, 0, '', ''),
(93, 'Kamilletuin', '', 'Een wat besloten deel met een hoge glijbaan en een toestel met rekstokken en andere klimmogelijkheden. Een grasveld met 2 ijzeren doelen.', 'Kamilletuin, Assen', 52.9993, 6.50973, 1, 21, 1, 0, 1, 1, 'Toestelspeeltuin', 'kamilletuin', '2017-09-17 20:02:08', 0, 0, 0, '', ''),
(94, 'Moerbeistraat', '', 'Glijbaan, huisje met glijbaan en een klimtoestel.', 'Moerbeistraat, Assen', 53.0021, 6.51068, 1, 21, 1, 0, 1, 0, 'Toestelspeeltuin', 'moerbeistraat', '2017-09-17 21:17:47', 0, 0, 0, '', ''),
(95, 'NAM locatie', '', 'In Kommerzijl is een kleine speeltuin geschikt voor kleintjes. Maar echt goed verstopt zit deze leuke houten toestellen speeltuin.Inclusief kabelbaal over de sloot!', 'Volg in Kommerzijl het fietspad naar Grijpskerk, dan kom je terecht in het fraai aangelegde natuurpark rondom de NAM locatie. Hier vind je vlak achter Kommerzijl een heerlijk speelterrein tussen de bloemetjes.', 53.2848, 6.32166, 1, 25, 1, 0, 1, 1, 'Toestelspeeltuin', 'nam-locatie', '2017-09-18 10:44:29', 0, 0, 0, '', ''),
(96, 'Waterspeeltuin Lauwersoog', '', 'Water, water en nog eens water. Met baggertoestel, kliedertafel, veel waterpompen, speelvis, en prachtige watersystemen waarbij samenwerken gewenst is.', 'Strandweg 1, tegenover restaurant Het Boze Wijf', 53.404, 6.21199, 1, 25, 1, 1, 1, 1, 'Toestelspeeltuin', 'waterspeeltuin-lauwersoog', '2017-09-18 11:13:57', 0, 0, 0, '', ''),
(97, 'Arjen Robben Veld Bedum', '', 'Voetbalveld met verlichting en watertappunt. Er zijn huisregels', 'Bedum waldadrift 37 ', 53.2962, 6.60968, 1, 11, 1, 0, 0, 1, 'Sportfaciliteit', 'arjen-robben-veld-bedum', '2017-09-18 20:59:47', 0, 0, 0, '', ''),
(98, 'Lijnbaan Bedum', '', 'Speeltuintje naast een sloot. Sloot is niet afgeschermd dus minder geschikt voor kleintjes. Wel lekker ruim. Veel gras.', 'De lijnbaan bedum', 53.2988, 6.60433, 1, 11, 1, 0, 1, 1, 'Toestelspeeltuin', 'lijnbaan-bedum', '2017-09-18 21:08:08', 0, 0, 0, '', ''),
(99, 'Natuurspeeltuin Voorschoten', 'http://natuurspeeltuinvoorschoten.nl', 'De Natuurspeeltuin Voorschoten is voor iedereen toegankelijk: jong en oud, klein en groot, valide en mindervalide. Vier van de vijf speelwerelden zijn ook voor kinderen in een rolstoel toegankelijk, onder meer door de aanleg van (half)verharde paden, brede bruggen en een brede tunnel. Daarnaast zijn de onderdelen die bediend kunnen worden, zoals de waterpompen en muziekpalen, op rolstoelhoogte. En uiteraard komt er een aangepast toilet op het terrein.\r\napril t/m oktober: 9.00-20.00 uur, november t/m maart: 9.00-17.00 uur', 'Veurseweg Voorschoten', 52.115, 4.43112, 1, 26, 2, 0, 1, 1, 'Natuurspeeltuin', 'natuurspeeltuin-voorschoten', '2017-09-19 19:07:12', 0, 0, 0, '', ''),
(100, '\'t BlÃ´de Fuottenpaad', '', 'Een waar speelfeest! Water, modder, glooiende grasveldjes, blubberige slootjes, gaten in de weg, doolhof, glibberige oversteekplaatsjes, een boomhut, watertjes waar je de ergste modder weer kunt afspoelen. Trek oude kleren aan en doe je schoenen uit. Neem een picknick mee en bewandel dit fantastische pad (in ieder geval 2 km, maar misschien ondertussen alweer langer). Voor de kleintjes is het voldoende om te spelen op de zandvlakte aan het water of in de teletubbie grasheuvels. De \'tocht\' is voor hen wat moeilijk. O ja, en lees bij de voorzieningen waterbak en zandbak zonder het woord \'bak\'.', 'Kaleweg, Opende', 53.183, 6.20487, 1, 25, 1, 1, 1, 1, 'Natuurspeeltuin', 't-blde-fuottenpaad', '2017-09-19 19:49:46', 0, 0, 0, '', ''),
(101, 'Hornhuizen', '', 'Een heel goed verstopte kleine leuke speeltuin.', 'Tussen Tammingsastraat nummer 10 en 12 loopt een heel smal paadje richting de speeltuin', 53.3875, 6.36377, 1, 25, 1, 1, 1, 0, 'Toestelspeeltuin', 'hornhuizen', '2017-09-20 12:11:31', 0, 0, 0, '', ''),
(102, 'Warffum', '', '', 'Beyerinckstraat  warffum', 53.3969, 6.5604, 1, 22, 1, 0, 1, 1, 'Toestelspeeltuin', 'warffum', '2017-09-19 22:12:11', 0, 0, 0, '', ''),
(103, 'Mercer Park', '', '', '2701 Bradford Dr, Iowa City, IA 52240, Verenigde Staten', 41.6458, -91.4955, 1, 28, 1, 0, 1, 1, 'Toestelspeeltuin', 'mercer-park', '2017-09-20 14:12:53', 0, 0, 0, '', ''),
(104, 'Niehove', '', 'Dorpsspeeltuin van Niehove', '', 53.2905, 6.36644, 1, 25, 1, 1, 1, 0, 'Toestelspeeltuin', 'niehove', '2017-09-21 09:23:07', 0, 0, 0, '', ''),
(106, 'Buurtspeeltuin in Germignaga, Italie', '', 'Leuke buurtspeeltuin in Germignaga, ItaliÃ«. Speeltuin mag niet meer betreden worden in de avonduren/nacht. Gratis parkeerplaatsen.', 'Germignaga, ItaliÃ«', 45.9942, 8.72201, 1, 24, 2, 1, 1, 1, 'Toestelspeeltuin', 'buurtspeeltuin-in-germignaga-italie', '2017-09-21 13:48:05', 0, 0, 0, '', ''),
(107, 'Parco Civico', '', 'Mooie speeltuin in park aan het meer van Lugano, tevens fitnessparcours aanwezig.', 'Lugano, Zwitserland', 46.0034, 8.96089, 1, 24, 1, 1, 1, 1, 'Toestelspeeltuin', 'parco-civico', '2017-09-21 13:55:48', 0, 0, 0, '', ''),
(108, 'De Mikkelhorst', 'https://www.mikkelhorst.nl/', 'Welkom bij Ecologische Zorgboerderij De Mikkelhorst! We zijn gelegen aan de rand van het groene Haren in de wijk Oosterhaar. Het is het een prachtige plek om te bezoeken of om te werken. Er is een kinderboerderij, tuinderij, theeschenkerij, houtkloverij en een winkel voor streekprodukten. Tijdens openingsuren is het terrein vrij toegankelijk.', 'Klaverlaan 37, 9753 BZ Haren', 53.1798, 6.62553, 1, 5, 2, 1, 1, 1, 'Kinderboerderij met speeltuin', 'de-mikkelhorst', '2017-09-22 13:32:20', 0, 0, 0, '', ''),
(109, 'Rabbijn Maarsenplein', '', 'In het centrum van den haag, uitgebreid klimrek, draaimolen, nestschommel. Omgeven door terrassen dus ouders kunnen zelf wat eten/drinken en kroost in de gaten houden. Er staan grote bomen voor schaduw, maar er zit helaas ook wat duivenpoep op de speeltoestellen en bankjes. ', 'Rabbijn Maarsenplein', 52.0758, 4.31482, 1, 9, 1, 0, 1, 1, 'Toestelspeeltuin', 'rabbijn-maarsenplein', '2017-09-23 14:13:48', 0, 0, 0, '', ''),
(110, 'Speelterrein ABC', 'speelterreinabc.blogspot.com', 'Stichting Speelterrein ABC', 'Allee, Hattem', 52.4707, 6.07395, 1, 18, 1, 1, 1, 0, 'Toestelspeeltuin', 'speelterrein-abc', '2017-09-24 15:35:19', 0, 0, 0, '', ''),
(111, 'Voetbalveld Mannagras', '', 'Groot voetbalveld met doelen. Er staat ook een klimrek.', 'Mannagras, Leeuwarden', 53.1854, 5.81477, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'voetbalveld-mannagras', '2017-09-24 17:23:43', 0, 0, 0, '', ''),
