(113, 'Buurtspeeltuin Duurschen II', '', '', 'Dreeuwing, Gieten', 52.9978, 6.77068, 1, 32, 1, 1, 1, 0, 'Toestelspeeltuin', 'buurtspeeltuin-duurschen-ii', '2017-09-26 16:41:18', 0, 0, 0, '', ''),
(114, 'Steringastraat', '', 'Buurtspeeltuin met een paar leuke toestellen en een pingpongtafel', 'G. Steringastraat, Groningen', 53.1909, 6.55477, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'steringastraat', '2017-09-27 11:04:16', 0, 0, 0, '', ''),
(115, 'Groen van Prinstererlaan', '', 'Kleine toestelspeeltuin, beetje verscholen gelegen aan een zijstraat van de Goeman Borgesiuslaan.', 'Groen van Prinstererlaan, Groningen', 53.1932, 6.59206, 1, 5, 1, 0, 1, 0, 'Toestelspeeltuin', 'groen-van-prinstererlaan', '2017-09-27 11:08:29', 0, 0, 0, '', ''),
(116, 'De Beestenborg', 'http://debeestenborg.webnode.nl/', 'Kinderboerderij en speeltuin de Beestenborg vind je in Groningen stad en is gelegen tussen de wijken Ulgersmaborg en Oosterhoogebrug. Het is een van de grootste kinderboerderijen van de stad en is alle 7 dagen van de week geopend! De speeltuin heeft heel bijzondere speeltoestellen zoals een kabelbaan en een familieschommel. Onze speeltuin is goedgekeurd door de speeltuinbende en dus ook toegankelijk voor kinderen met een beperking.', 'Akeleiweg 69, Groningen', 53.2312, 6.5976, 1, 33, 2, 0, 1, 1, 'Kinderboerderij met speeltuin', 'de-beestenborg', '2017-09-28 13:01:31', 0, 0, 0, '', ''),
(117, 'Eelderbaan', 'https://dierenweidesgroningen.nl/eelderbaan/', 'De Dierenweide Eelderbaan is het karakteristieke gebouw op de hoek van Vinkhuizen en de Held. Het is een prachtige plek om kennis te maken met mens en dier. Kom vooral langs: er valt altijd van alles te beleven!', 'Kornalijnlaan 7, 9743 JK Groningen', 53.2282, 6.52151, 1, 5, 2, 1, 1, 1, 'Kinderboerderij met speeltuin', 'eelderbaan', '2017-09-29 09:07:02', 0, 0, 0, '', ''),
(118, 'Dierenweide Minerva', '', 'Kleine kinderboerderij met speeltuin erbij.', 'Roderwolderdijk, Hoogkerk', 53.2023, 6.5054, 1, 5, 1, 1, 1, 1, 'Kinderboerderij met speeltuin', 'dierenweide-minerva', '2017-09-29 09:10:47', 0, 0, 0, '', ''),
(119, 'Poolsterlaan', '', '', 'Poolsterlaan, Groningen', 53.2301, 6.5348, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'poolsterlaan', '2017-09-29 16:44:05', 0, 0, 0, '', ''),
(120, 'Jaagpad I', '', '', 'Langs het Jaagpad', 53.2235, 6.53965, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'jaagpad-i', '2017-09-29 16:50:38', 0, 0, 0, '', ''),
(121, 'Jaagpad II', '', 'Heel klein speeltuintje met een hek Ã©n een haag eromheen.', 'Langs het Jaagpad', 53.223, 6.54025, 1, 5, 1, 1, 1, 0, 'Toestelspeeltuin', 'jaagpad-ii', '2017-09-29 16:52:05', 0, 0, 0, '', ''),
(122, 'Mesdagplein', '', '', 'H.W. Mesdagplein, Groningen', 53.2164, 6.55104, 1, 5, 1, 1, 0, 0, 'Toestelspeeltuin', 'mesdagplein', '2017-09-29 17:03:55', 0, 0, 0, '', ''),
(123, 'Geerstuk (Delfzijl)', '', 'Klein speeltuintje, midden in een woonwijk. Veel gras en ruimte', 'geerstuk delfzijl', 53.3279, 6.8934, 1, 11, 1, 1, 1, 0, 'Toestelspeeltuin', 'geerstuk-delfzijl', '2017-09-30 09:18:07', 0, 0, 0, '', ''),
(124, 'Stadspark Delfzijl', '', 'Grote, en erg leuke speeltuin in het stadspark van Delfzijl. Veel houten speeltoestellen (oa een piratenschip). Ruim opgezet. Er is een strandje aan een eendenvijver en watertoestellen om mee te spelen (oa waterpomp en waterbakken). Veel te doen! Parkeren kan eenvoudig op de parkeerplaats bij De Wending/Ede Staalstraat.', 'Stadspark Delfzijl', 53.3345, 6.91243, 1, 11, 1, 1, 1, 1, 'Toestelspeeltuin', 'stadspark-delfzijl', '2017-09-30 09:33:26', 0, 0, 0, '', ''),
(125, 'Lunetstraat Delfzijl', '', 'Klein wijkspeeltuintje met een paar speeltoestellen (dichtbij de grote speeltuin in het Stadpark)', 'Lunetstraat Delfzijl', 53.3355, 6.91397, 1, 11, 1, 1, 1, 0, 'Toestelspeeltuin', 'lunetstraat-delfzijl', '2017-09-30 09:29:45', 0, 0, 0, '', ''),
(126, 'Skatebaan Stadspark Delfzijl', '', 'Skatebaan', 'Tunnelpad Delfzijl', 53.3332, 6.91315, 1, 11, 1, 0, 0, 1, 'Sportfaciliteit', 'skatebaan-stadspark-delfzijl', '2017-09-30 09:45:54', 0, 0, 0, '', ''),
(127, 'Bedum De Eiken', '', 'Volledig vernieuwd in september 2017. Nu ook met steltenpad, stapstammen, palenwoud, schommels, duikelrek en kabelbaan. (foto is nog van de oude speeltuin)', 'De Eiken Bedum', 53.2998, 6.61026, 1, 11, 1, 1, 1, 1, 'Toestelspeeltuin', 'bedum-de-eiken', '2017-09-30 11:15:45', 0, 0, 0, '', ''),
(128, 'Almere Evenaar Tennis', '', 'Gratis toegankelijke tennisbaan/tenniskooi', 'Almere Evenaar', 52.4051, 5.30978, 1, 11, 1, 0, 1, 1, 'Sportfaciliteit', 'almere-evenaar-tennis', '2017-09-30 11:21:04', 0, 0, 0, '', ''),
(129, 'Almere Evenaar Basketbalveld', '', 'Basketbalcourt / Basketbal kooi met waterpunt', 'Almere Evenaar', 52.404, 5.30718, 1, 11, 1, 0, 1, 1, 'Sportfaciliteit', 'almere-evenaar-basketbalveld', '2017-09-30 11:23:35', 0, 0, 0, '', ''),
(130, 'Almere Evenaar Voetbalveld', '', 'Gratis toegankelijk voetbalveld /  voetbalkooi. Er is ook een waterpunt', 'Almere Evenaar', 52.4033, 5.30551, 1, 11, 1, 0, 1, 1, 'Sportfaciliteit', 'almere-evenaar-voetbalveld', '2017-09-30 11:25:14', 0, 0, 0, '', ''),
(131, 'Almere Evenaar Skatebaan', '', 'Grote skatebaan!! Langs de hele Evenaar loopt tevens een hardlooppad met afstandsmarkeringen.', 'almere Evenaar', 52.402, 5.3025, 1, 11, 1, 0, 1, 1, 'Sportfaciliteit', 'almere-evenaar-skatebaan', '2017-09-30 11:29:36', 0, 0, 0, '', ''),
(132, 'Almere Dagenweg', '', 'Klein speeltuintje in woonwijk met leuk klimtoestel en trapveldje. Er is parkeermogelijkheid.', 'almere dagenweg', 52.4067, 5.27866, 1, 11, 1, 1, 1, 0, 'Toestelspeeltuin', 'almere-dagenweg', '2017-09-30 11:47:41', 0, 0, 0, '', ''),
(133, 'Almere Staakmolenstraat', '', 'Wijkspeeltuintje, omheind door een heggetje', 'Almere strijkmolenweg', 52.4007, 5.27387, 1, 11, 1, 1, 1, 1, 'Toestelspeeltuin', 'almere-staakmolenstraat', '2017-09-30 11:57:46', 0, 0, 0, '', ''),
(134, 'Almere Constant Permekehof', '', 'Klein speeltuintje maar de speeltoestellen zijn goed onderhouden.', 'Constant Permekehof, Almere', 52.3777, 5.25653, 1, 11, 1, 1, 1, 0, 'Toestelspeeltuin', 'almere-constant-permekehof', '2017-09-30 12:06:22', 0, 0, 0, '', ''),
(135, 'Almere Oleanderstraat', '', 'Lekker ruim omgezet speeltuintje met veel gras.', 'oleanderstraat almere', 52.3865, 5.28625, 1, 11, 1, 1, 1, 0, 'Toestelspeeltuin', 'almere-oleanderstraat', '2017-09-30 12:13:50', 0, 0, 0, '', ''),
(136, 'Belevingspad Het Roekpad in Echten (Kraaienbos)', 'http://keivaneendorp.nl/wp-content/uploads/2015/05/Bord-de-Belle.jpg', 'Het Roekpad (2015) in Echten is een belevingspad in een bos. Je kunt hier echt spelen in het bos en de natuur ontdekken met je vijf zintuigen. Loek de Roek wijst je de route tijdens de belevenis wandeling van 1 kilometer. Je zintuigen staan centraal, zo kan je horen, proeven, ruiken, voelen en zien! Voor kinderen en volwassenen die visueel gehandicapt zijn, staat de tekst op de borden in Braille. Wil jij ook braille leren lezen? Loek de Roek heeft leuke vragen bedacht zodat jij de Braille kunt ontcijferen! Gratis toegang! Open tussen zonsopgang en zonsondergang.\r\nZuidwolderweg 2a in Echten (De start is bij Visio, midden in Echten)', 'zuidwolderweg 2a echten', 52.7133, 6.39826, 1, 11, 1, 1, 1, 1, 'Natuurspeeltuin', 'belevingspad-het-roekpad-in-echten-kraaienbos', '2017-09-30 12:50:42', 0, 0, 0, '', ''),
(137, 'Natuurspeelplaats Vos en Bos (Speelbos)', '', 'Pas aangelegd (2017) en superleuk speelbos, gemaakt door buurtbewoners. Er zijn boomstammen om op/mee te spelen. Er zijn (boom)hutten die de kinderen kunnen afbouwen, er is een labyrinth en bankjes om op te zitten. Toegankelijk dmv snipperpaden.', 'croonhoven hoogezand', 53.1587, 6.78273, 1, 11, 1, 1, 1, 1, 'Toestelspeeltuin', 'natuurspeelplaats-vos-en-bos-speelbos', '2017-09-30 12:49:43', 0, 0, 0, '', ''),
(138, 'Speelbos Emmerdennen', 'https://www.staatsbosbeheer.nl/natuurgebieden/hondsrug/bezienswaardigheden/speelbos-emmerdennen', 'Het (gratis) speelbos Emmerdennen is een \'natuurlijke speeltuin\', het is geen gewone speeltuin. Je kunt er in bomen klimmen en over slootjes springen. Boomhutten en bruggetjes bouwen. Verstoppertje spelen of vlag veroveren. Een bos waar je buiten de paden mag komen en waar je je lekker kunt uitleven. Het enige wat er niet mag is vuurtje stoken en ook spijkers zijn verboden! ', 'oude markeweg emmen', 52.7858, 6.92953, 1, 11, 1, 1, 1, 1, 'Natuurspeeltuin', 'speelbos-emmerdennen', '2017-11-10 11:24:07', 4, 1, 4, '', ''),
(139, 'Belevingspad Veeningen', 'http://www.ddveeningen.nl/het-dorp/groene-hart/belevingspad', 'Altijd open en gratis. Het belevingspad begint in de speeltuin, waar voor alle kinderen iets is: glijbanen, kabelbaan, schommels etc. Volg dan de pijlen en je komt een insectenhotel tegen en een sportkooi, houten dieren, boomhutten, jeu de boulesbaan, klimtouwen, een tipi en een minifiets-crossbaan. Na een paar kilometer zie je de speeltuin weer in de verte. Er is ook een uitgezette speur/wandeltocht. De route kun je uitprinten vanaf de site (zie link).\r\n\r\n', 'dorpshuisstraat 43 veeningen', 52.6686, 6.37091, 1, 11, 1, 1, 1, 1, 'Natuurspeeltuin', 'belevingspad-veeningen', '2017-09-30 13:52:52', 0, 0, 0, '', ''),
(140, 'Belevingspad Hoogersmilde (Punthorst)', '', 'Belevingswandelroute van 2,5 Km door het Nationaal park Drents Friese Wold. Op de route kom je vanalles tegen: een sporenpad  (dierensporen zoeken), een heus vliegtuig, slangenkuil, stronkenstraat,  een waterpomp, Grote houten dieren op de Dierendriesprong, een keienpad met 45 grote keien om op te spelen, een uitkijkpunt over de heide, een boomstammentrap en een Veenhuis - (Kijk hoe de allereerste bewoners van dit gebied honderden jaren terug hebben geleefd)\r\nBij de parkeerplaats van het Drents Friese Wold aan de Bosweg in Hoogersmilde kun je starten met de route. Er zijn borden geplaatst die u naar het belevingspad toe leiden. Je kan ook starten vanaf camping De ReeÃ«nwissel (vanaf daar is het 300m lopen naar het Belevingspad).', 'bosweg hoogersmilde', 52.9083, 6.37327, 1, 11, 1, 1, 1, 1, 'Natuurspeeltuin', 'belevingspad-hoogersmilde-punthorst', '2017-09-30 18:20:25', 0, 0, 0, '', ''),
(141, 'Belevingspad Struunpad Koekangerveld', 'http://struunpad.nl/', 'Boswandeling van ongeveer 1 km lang. Geen speeltoestellen onderweg maar wel een afwisselende route en geschikt voor kinderen. De start is bij dorpshuis De Veldhoek (ruinerweg) in Koekangerveld', 'Ruinerweg 24a koekangerveld', 52.7145, 6.33605, 1, 11, 1, 1, 1, 1, 'Natuurspeeltuin', 'belevingspad-struunpad-koekangerveld', '2017-09-30 14:28:20', 0, 0, 0, '', ''),
(142, 'Belevingsbos Kerkenveld', '', 'In 2017 geopend! Een leuk speel-, doe-, wandel,- en belevingsbos. Is tevens rolstoeltoegankelijk. Een leuke plek waar kinderen heerlijk in de natuur kunnen spelen. Ook hangen er vogelhuisjes en is er een theater in het bos.', 'Jan Haarstraat Kerkenveld', 52.667, 6.50151, 1, 11, 1, 1, 1, 1, 'Natuurspeeltuin', 'belevingsbos-kerkenveld', '2017-09-30 14:50:44', 0, 0, 0, '', ''),
(143, 'Speeltuin vereniging De Bulties Kerkenveld', '', 'Vlak naast het Belevingsbos Kerkenveld. Leuke grote speeltuin met allerlei klimtoestellen, schommels, zand- en waterbak, basketbalnet, tafeltennistafel en picknicktafels en bankjes voor ouders e.d. In de zomer is er een klein peuterzwembad.', 'Jan Haarweg Kerkenveld', 52.6678, 6.50059, 1, 11, 1, 1, 1, 1, 'Toestelspeeltuin', 'speeltuin-vereniging-de-bulties-kerkenveld', '2017-09-30 15:02:15', 0, 0, 0, '', ''),
(144, 'Wandelpad: het Houten Pad van Theodoor', 'https://www.drenthe.nl/nl/natuur-parken/belevingspaden-en-speelbossen/353350722/houten-pad-van-theodoor', 'Het Houten Pad van Theodoor is een houten pad/route door het bos. Soms over de grond, soms hoger tussen de bomen door. Het pad hoort bij het verhaal over het avontuurlijke varkentje Theordoor. In het begin is het pad makkelijk te lopen. Verderop moet je oppassen! Dan loop je weer hoog tussen de bomen en even later weer laag langs het water. Vanaf de Brink in het dorp Orvelte is het Pad van Theodoor goed aangegeven. De start van het pad ligt (vanaf daar) ca 1 km verderop in het bos. Volg de roze paaltjes.', 'De Brink Orvelte', 52.8463, 6.65578, 1, 11, 1, 1, 1, 1, 'Natuurspeeltuin', 'wandelpad-het-houten-pad-van-theodoor', '2017-09-30 15:09:13', 0, 0, 0, '', ''),
(145, 'Speelbos Lorken Drouwen', '', 'Speelbos Lorken ligt vlak naast het Boomkroonpad. Het speelbos is gratis. (Het Boomkroonpad niet). Je kan er fijn hutten bouwen, spelen en klimmen/klauteren.', 'Steenhopenweg 4 Drouwen', 52.9498, 6.74496, 1, 11, 1, 1, 1, 1, 'Natuurspeeltuin', 'speelbos-lorken-drouwen', '2018-08-24 09:12:47', 0, 0, 0, '', ''),
(146, 'Speelbos Gilze', 'https://speelbosgilze.nl/', 'Speelbos met allerlei houten speeltoestellen. Je kan er heerlijk klimmen en klauteren Geschikt voor kinderen tot ongeveer 14 jaar. De rode draad in het bos is de mysterieuze en verlegen REUZIN. Ze laat zich niet graag zien, maar laat wel sporen na. Ze vermaakt de kinderen graag met extra spelsuggesties en uitdagende vragen.', 'Nerhoven Gilze', 51.5545, 4.94915, 1, 11, 1, 1, 1, 0, 'Natuurspeeltuin', 'speelbos-gilze', '2017-09-30 18:08:10', 0, 0, 0, '', ''),
(147, 'Ulvenhout Rooiakker', '', 'Fijne ruime speeltuin in een woonwijk. Veel te doen.', 'Rooiakker ulvenhout', 51.5516, 4.79975, 1, 11, 1, 1, 1, 0, 'Toestelspeeltuin', 'ulvenhout-rooiakker', '2017-09-30 18:15:54', 0, 0, 0, '', ''),
(149, 'Zandbak Wilgenhof', '', '', 'Wilgenhof, Hattem', 52.4779, 6.06208, 1, 5, 1, 1, 1, 0, 'Toestelspeeltuin', 'zandbak-wilgenhof', '2017-09-30 22:51:21', 0, 0, 0, '', ''),
(150, '\'t Vossenhol', '', 'Flinke speeltuin met allerlei leuke toestellen.', 'Scheuningskamp, Beilen', 52.8718, 6.52299, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 't-vossenhol', '2017-10-01 15:47:35', 0, 0, 0, '', ''),
(151, 'Voet- en volleybalveld Scheuningskamp', '', '', 'Scheuningskamp, Beilen', 52.8714, 6.52375, 1, 5, 1, 0, 1, 1, 'Sportfaciliteit', 'voet--en-volleybalveld-scheuningskamp', '2017-10-01 15:50:30', 0, 0, 0, '', ''),
(152, 'Speeltuin Berkenweg', '', 'Kleine speeltuin met 2 schommels, 3 klimpalen en glijbaan... en de grond is schoon geel zand.', 'Berkenweg 28/28a  9603DK Hoogezand', 53.1485, 6.76223, 1, 31, 1, 1, 1, 0, 'Toestelspeeltuin', 'speeltuin-berkenweg', '2017-10-02 13:03:21', 0, 0, 0, '', ''),
(153, 'Speeltuin Stadspark', '', 'Fantastische speeltuin met heel veel leuke toestellen.', 'Stadspark, Groningen', 53.2059, 6.54577, 1, 5, 1, 1, 1, 1, 'Toestelspeeltuin', 'speeltuin-stadspark', '2017-10-03 09:13:14', 0, 0, 0, '', '');
INSERT INTO `speeltuin` (`id`, `naam`, `link`, `omschrijving`, `locatie_omschrijving`, `lat`, `lon`, `status_id`, `author_id`, `public`, `agecat_1`, `agecat_2`, `agecat_3`, `speeltuintype`, `seo_url`, `modified_on`, `total_rating`, `times_rated`, `avg_rating`, `openingstijden`, `vergoeding`) VALUES
(154, 'Kinderboerderij Stadspark', '', 'Grote kinderboerderij. \'s Zomers open van 9 tot 17:30 uur, \'s winters van 9 tot 17 uur.', 'Stadspark, Groningen', 53.206, 6.54675, 1, 5, 2, 1, 1, 1, 'Kinderboerderij', 'kinderboerderij-stadspark', '2017-10-03 09:16:45', 0, 0, 0, '', ''),
(155, 'Speeltuin Peizerweg', '', 'Ruim speelveld met o.a. voetbaldoelen en kabelbaan.', 'Peizerweg, Groningen', 53.2063, 6.53267, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'speeltuin-peizerweg', '2017-10-03 09:26:05', 0, 0, 0, '', ''),
(156, 'Duisenberg', '', 'Achter het Duisenberg-gebouw van de universiteit bevindt zich een soort hangplek voor studenten met schommels en een groot houten klim-/zittoestel.', 'Landleven, Zernike-campus, Groningen', 53.2392, 6.53376, 1, 5, 1, 0, 0, 1, 'Toestelspeeltuin', 'duisenberg', '2017-10-13 08:51:51', 0, 0, 0, '', ''),
(157, 'Voet- en basketbalkooi Canadalaan', '', '', 'Canadalaan, Groningen', 53.2022, 6.56265, 1, 5, 1, 0, 0, 1, 'Sportfaciliteit', 'voet--en-basketbalkooi-canadalaan', '2017-10-13 15:39:16', 0, 0, 0, '', ''),
(158, 'Speeltuin Canadalaan', '', '', 'Canadalaan, Groningen', 53.2019, 6.56252, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'speeltuin-canadalaan', '2017-10-13 20:51:36', 0, 0, 0, '', ''),
(159, 'Nassauplein', '', 'Buurtspeeltuin met groot grasveld erbij.', 'Nassauplein, Groningen', 53.2207, 6.54551, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'nassauplein', '2017-10-13 20:52:33', 0, 0, 0, '', ''),
(160, 'Haagse bos speeltuin', '', 'Mooie natuurspeeltuin in het Haagse bos. Klimmen, evenwichtsbalk, loopbruggen, leuke kabelbaan over een modderpoel. Natuurlijk heerlijk om te combineren met een wandeling door het bos (loofbomen, vijvers).', '', 52.0863, 4.32929, 1, 9, 1, 1, 1, 1, 'Natuurspeeltuin', 'haagse-bos-speeltuin', '2017-10-14 14:47:17', 0, 0, 0, '', ''),
(161, 'Rondom de maredijk', 'http://www.svmaredijk.nl', 'Goed onderhouden speeltuin. Toegang is 50 cent per kind. Vriendelijke beheerders, nette wc\'s en in de zomer een zwembadje voor kinderen tot 9 jaar. Voor de kleinsten een apart omheind speelveldje met onder meer een waterpomp en voor de groteren een voetbal-/basketbalveld en toestellen voor wat hoger klimmen. IJsjes kosten tot 1 euro en koffie 50 cent. Je kunt ook lid worden voor ongeveer 15 euro per jaar. Je kunt dan het mooie zaaltje met bar huren en hebt onbeperkt gratis toegang.', 'Maredijk 100, Leiden\r\n', 52.1676, 4.48908, 1, 35, 1, 1, 1, 1, 'Toestelspeeltuin', 'rondom-de-maredijk', '2017-10-14 22:49:10', 0, 0, 0, '', ''),
(162, 'Speeltuinvereniging Vogelenwijk', 'http://vogelwijk.nl/', 'Geweldige speeltuin met  voor elk wat wils. Hier worden ook vaak activiteiten georganiseerd zoals kledingruilmarkten en je jaarlijkse zomercamping voor leden. Apart gedeelte voor de kleinsten. Voor de groteren een slingertoestel en, soms wat viezige, waterplas. Gebouwtje met bar is af te huren als je lid wordt, dan ook gratis toegang. Anders 50 cent per kind te betalen in de brievenbus bij het hek. Wc in het gebouw en anders is de buitenwc open.', 'Nachtegaallaan 25, Leiden', 52.1724, 4.46858, 1, 35, 2, 1, 1, 1, 'Toestelspeeltuin', 'speeltuinvereniging-vogelenwijk', '2017-10-14 22:58:39', 0, 0, 0, '', ''),
(163, 'Speelplein de Vrije School', '', 'Plein van de Vrije School in Almelo (Schelfhorst)', 'Grasbroek, Almelo', 52.374, 6.6787, 1, 18, 2, 0, 1, 1, 'Toestelspeeltuin', 'speelplein-de-vrije-school', '2017-10-15 16:32:15', 0, 0, 0, '', ''),
(164, 'Kinderboerderij de Lariks', 'http://www.kinderboerderijdelariks.nl/', '', 'Laak 1A, Assen', 52.9999, 6.54272, 1, 36, 1, 1, 1, 1, 'Kinderboerderij', 'kinderboerderij-de-lariks', '2017-10-17 21:32:03', 0, 0, 0, '', ''),
(165, 'Kinderboerderij Emmelerbos', '', 'Hele mooie kinderboerderij midden in het bos met grote nieuwe speeltuin.', 'emmelerbos \r\n', 52.7219, 5.75715, 1, 38, 2, 1, 1, 1, 'Kinderboerderij met speeltuin', 'kinderboerderij-emmelerbos', '2017-10-18 09:25:54', 0, 0, 0, 'maandag gesloten\r\nandere dagen 11:00 - 16:00', ''),
(166, 'Goudreinet', '', 'Klein speeltuintje met rekstokken en kleine glijbaan, wipmotor en picknickbank.', 'Goudreinet', 53.0052, 6.50298, 1, 21, 1, 0, 1, 0, 'Toestelspeeltuin', 'goudreinet', '2017-10-18 16:13:07', 0, 0, 0, '', ''),
(167, 'Karmijn', '', 'Speeltuin met veel gras, 2 zitbankjes, een opstelling van boomstammen om overheen te lopen (evenwicht), rekstokken en een kleine glijbaan.', 'Karmijn', 53.0053, 6.50543, 1, 21, 1, 0, 1, 0, 'Toestelspeeltuin', 'karmijn', '2017-10-18 16:20:18', 0, 0, 0, '', ''),
(168, 'Schoolplein OBS Kloosterveen en CJBS de Kloostertuin', '', 'Groot schoolplein achter de scholen met een omheind voetbalveld, een kleinere voetbalkuil, een tafeltennistafel, een plein met basketnet, diverse klimtoestellen en picknickbanken.', 'Achter de scholen', 53.0043, 6.50551, 1, 21, 2, 0, 1, 1, 'Toestelspeeltuin', 'schoolplein-obs-kloosterveen-en-cjbs-de-kloostertuin', '2017-10-18 16:37:32', 0, 0, 0, 'Na schooltijd toegankelijk. ', ''),
(169, 'Jeux de Boulesbaan', '', 'Zelf ballen meenemen en misschien een hark. Het onderhoud valt wat tegen.', 'Hazelaarhof', 53.0034, 6.50687, 1, 21, 1, 0, 0, 1, 'Sportfaciliteit', 'jeux-de-boulesbaan', '2017-10-18 16:33:50', 0, 0, 0, '', ''),
(170, 'Delbar-Elstar', '', 'Grasveld met 2 schommels, klimtoestel en bankjes.', 'Tussen Delbar en Elstar', 53.0031, 6.50349, 1, 21, 1, 0, 1, 1, 'Toestelspeeltuin', 'delbar-elstar', '2017-10-18 16:44:52', 0, 0, 0, '', ''),
(171, 'Elstar-Gloster', '', 'Wiptoestel dat er uitziet als wipwap, klimtoestel, rekstokken en een wiebelbrug.', 'Tussen Elstar en Gloster', 53.004, 6.50329, 1, 21, 1, 0, 1, 1, 'Toestelspeeltuin', 'elstar-gloster', '2017-10-18 16:54:28', 0, 0, 0, '', ''),
(172, 'Kleuterplein CJBS de Kloostertuin', '', 'Schooltuin met picknickbanken, rekstokken en zandbak aan de voorkant van de school.', 'Schoolplein voorkant CJBS de Kloostertuin', 53.0039, 6.50658, 1, 21, 2, 0, 1, 0, 'Toestelspeeltuin', 'kleuterplein-cjbs-de-kloostertuin', '2017-10-18 17:01:05', 0, 0, 0, 'Vrij toegankelijk na schooltijd (continuerooster tot 14:00 uur).', ''),
(173, 'De Tjalk', '', 'Groot grasveld met speelhuisje met glijbaan en een kraaiennest.', 'De Tjalk', 52.997, 6.51351, 1, 21, 1, 0, 1, 1, 'Toestelspeeltuin', 'de-tjalk', '2017-10-19 21:26:24', 0, 0, 0, '', ''),
(174, 'De Aak', '', 'Groot grasveld met een rekstok. Helaas is de speelboot (tijdelijk?) verwijderd door de gemeente.', 'De Aak', 52.9975, 6.51552, 1, 21, 1, 0, 1, 1, 'Toestelspeeltuin', 'de-aak', '2018-11-03 15:20:07', 0, 0, 0, '', ''),
(175, '\'t Zwien', '', 'Kinderboerderij is een groot woord, maar je kunt hier wel heel leuk kijken bij de varkens en de biggetjes.', 'Lutmarsweg, Gees', 52.7527, 6.68959, 1, 5, 1, 0, 1, 1, 'Kinderboerderij', 't-zwien', '2017-10-23 20:48:06', 0, 0, 0, '', ''),
(176, 'Zuster Mohrpark', '', 'In het net opgeknapte Zuster Mohrpark bevinden zich o.a. een hertenkamp en een verzameling fitness-toestellen.', 'Zuster Mohrpark, Oosterhesselen', 52.7553, 6.72332, 1, 5, 1, 1, 1, 1, 'Kinderboerderij met speeltuin', 'zuster-mohrpark', '2017-10-25 14:35:06', 0, 0, 0, '', ''),
(177, 'Natuurspeeltuin Iemingecamp', '', 'Avontuurlijke speeltoestellen rondom een klein stroompje. Topstuk is de reusachtige glijbaan. Loopt aan de zuidkant door in een soort teletubbielandschap met nog wat gewone toestellen en een jeu-de-boulesbaan.', 'Iemingecamp, Emmen', 52.7842, 6.92989, 1, 5, 1, 0, 0, 1, 'Natuurspeeltuin', 'natuurspeeltuin-iemingecamp', '2017-10-25 17:52:42', 0, 0, 0, '', ''),
(178, 'Speeltuin Smedingeslag', '', 'Kleine speeltuin met schommels en grote glijbaan.', 'Smedingeslag, Emmen', 52.7818, 6.9312, 1, 5, 1, 0, 1, 0, 'Toestelspeeltuin', 'speeltuin-smedingeslag', '2017-10-25 17:51:11', 0, 0, 0, '', ''),
(179, 'Sportpark Smedingeslag', '', '', 'Smedingeslag, Emmen', 52.7814, 6.93108, 1, 5, 1, 0, 1, 1, 'Sportfaciliteit', 'sportpark-smedingeslag', '2017-10-25 16:25:58', 0, 0, 0, '', ''),
(180, 'De Hunze', '', 'Rekstokken en een klimtoestel', 'Aan kruizing Hunze en Bitse', 52.9953, 6.54193, 1, 21, 1, 0, 1, 1, 'Toestelspeeltuin', 'de-hunze', '2017-10-25 21:32:57', 0, 0, 0, '', ''),
(181, 'De Naoberhoeve Erica', '', '', 'Semstraat, Erica ', 52.7089, 6.93354, 1, 41, 1, 1, 1, 0, 'Kinderboerderij met speeltuin', 'de-naoberhoeve-erica', '2017-10-25 22:20:19', 0, 0, 0, '', ''),
