(183, 'Speeltuintje Havenstraat Noordbroek', '', 'Kleine, door de gemeente onderhouden speeltuin op een groot grasveld. Er zit een laag hek omheen. Naast de speeltuin is een hangplek voor tieners (waar ze letterlijk aan 2 toestellen kunnen hangen, maar ik zie er nooit oudere kinderen). Favoriet bij mijn dochter: draaiding met 3 fietsjes waarop ze eindeloos rondjes kan fietsen. Minder fijn: pas op hondenpoep rond (gelukkig niet op) de speeltuin.', 'Havenstraat Noordbroek', 53.1926, 6.87166, 1, 42, 1, 1, 1, 0, 'Toestelspeeltuin', 'speeltuintje-havenstraat-noordbroek', '2017-10-30 20:50:36', 0, 0, 0, '', ''),
(184, 'Johan Dijkstralaan', '', 'Gelegen aan de Hoogkerk-kant van recreatieplas Ruskenveen. Mooie grote glijbaan. Omheind aan de waterkant', 'Johan Dijkstralaan, Hoogkerk', 53.2048, 6.51449, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'johan-dijkstralaan', '2017-11-03 09:24:22', 0, 0, 0, '', ''),
(185, 'De Klencke', '', 'Basketbalveld en skatebaan', 'De Klencke, Zuidlaren', 53.0766, 6.69992, 1, 5, 1, 0, 1, 1, 'Sportfaciliteit', 'de-klencke', '2017-11-05 22:31:11', 0, 0, 0, '', ''),
(186, 'Gazellenlaan', '', 'Leuke toegankelijke speeltuin met glijbaan en mooie nestschommel. ', 'Gazellenlaan, Kloosterveen', 53, 6.51976, 1, 21, 1, 1, 1, 1, 'Toestelspeeltuin', 'gazellenlaan', '2017-11-09 23:01:24', 0, 0, 0, '', ''),
