(189, 'Speeltuin bij Paviljoen AppÃ¨lbergen', '', 'Middenin het bos, naast het paviljoen, waar je wat kunt eten en drinken, ligt een grote, altijd toegankelijke speeltuin. Met apart gedeelte voor de kleinsten. Blikvanger is de grote roze olifant met glijbaan en schommels. Vlakbij enkele grasvelden waar je kunt voetballen, volleyballen etc.', 'Hoge Heereweg, Glimmen', 53.1366, 6.63956, 1, 5, 1, 1, 1, 1, 'Toestelspeeltuin', 'speeltuin-bij-paviljoen-applbergen', '2017-11-12 21:30:54', 0, 0, 0, '', ''),
