(191, 'speeltuin bij Jumbo de Beren', '', 'Speeltuin met enkele toestellen bij winkelcentrum de Beren in groningen. Leuk voor na het boodschappen doen!', '', 53.2263, 6.56293, 1, 8, 1, 1, 1, 0, 'Toestelspeeltuin', 'speeltuin-bij-jumbo-de-beren', '2017-11-21 16:12:34', 0, 0, 0, '', ''),
