(195, 'Buurtspeeltuin Riedstraat', '', 'Deze speeltuin is met een hoog hek omheind waardoor kleintjes niet weg kunnen lopen. Er is een klimrek, zandbak, nestschommel, speelhuisje, ea.', 'Riedstraat, Harlingen', 53.178, 5.42796, 1, 9, 2, 1, 1, 0, 'Toestelspeeltuin', 'buurtspeeltuin-riedstraat', '2017-11-22 06:25:56', 0, 0, 0, '', ''),
(196, 'Speeltuin naast JOP-gebouw', '', 'Leuk speeltuintje bij een mooi park.\r\n\r\nKen je deze speeltuin? Kun je ons dan laten weten wat voor voorzieningen hier nog meer zijn? Foto\'s zijn ook van harte welkom!', 'Oosterpark naast het JOP-gebouw nabij het Treslinghuis, Groningen', 53.2269, 6.58345, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'speeltuin-naast-jop-gebouw', '2017-11-22 16:22:59', 0, 0, 0, '', ''),
