(222, 'Speeltuin Isabellaland', '', 'Leuke nieuwe speeltuin in Den Haag.\r\nOndergrond zand, voor groot en klein .', 'Isabellaland, Den Haag', 52.0974, 4.36655, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'speeltuin-isabellaland', '2018-03-14 14:08:11', 0, 0, 0, '', ''),
(223, 'Bongelbult', '', 'Grote speeltuin met klimrek grote en kleine en rond draaiende glijbanen, schommels, vogelnest,  wipwap,  duikelstangen, kabelbaan,  speelhuisje, voetbal goals, wipkippen en nog veel meer. Uren speelplezier voor jong en oud.', 'Kosterijweg 12, Westeremden', 53.345, 6.71026, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'bongelbult', '2018-03-14 14:08:43', 0, 0, 0, '', ''),
(226, 'Sportspeeltuin Hillesluis', '', 'Sportspeeltuin Hillesluis: gevestigd in de wijk Hillesluis te Rotterdam Zuid, met Johan Cruijff voetbalveld.', 'Vlasakkerstraat, Rotterdam Zuid', 51.8925, 4.5174, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'sportspeeltuin-hillesluis', '2018-03-14 14:09:28', 0, 0, 0, '', ''),
(229, 'Fongersplaats', '', '', '', 53.208, 6.57202, 1, 53, 1, 1, 1, 1, 'Toestelspeeltuin', 'fongersplaats', '2018-03-13 17:41:19', 0, 0, 0, '', ''),
(230, 'Toscamini', '', '#Schommel met normale zit en babyzit\r\n#Dreumes glijbaan. \r\n#Groot toestel met: \r\n1 kleuter glijbaan\r\n1 hoge glijbaan\r\nWiebelbrug\r\nEvenwichtsbalken van de ene kant naar de andere kant.\r\nHuisje onderin.\r\n#wipkip\r\n#een toestel waar je je aan op kunt trekken, ringen zwaaien enz.\r\n#rekstokken \r\n#wip\r\n\r\nDat alles op een kunstgrasmat met daaromheen een echt grasveld.\r\n\r\nMinpunten. Niet met de auto toegankelijk en er zijn geen bankjes of andere zitmogelijkheden.\r\n', 'Toscaninistraat Den Haag', 52.0609, 4.24491, 1, 52, 1, 1, 1, 0, 'Toestelspeeltuin', 'toscamini', '2018-03-13 17:44:00', 0, 0, 0, '', ''),
(231, 'Wezenlandenpark ', '', 'Speeltuin: schommelen, glijbaan, zand, wipwap enz enz. voor de jonge kinderen. Iets verder het pad volgen en daar heb je grote klimtoestellen voor oudere kinderen!\r\nKinderboerderij: je mag de dieren eten geven, in het weiland met de geitjes enz.', 'Park de Wezenlanden Zwolle', 52.5076, 6.10855, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'wezenlandenpark-', '2018-03-14 14:09:46', 0, 0, 0, '', ''),
(232, 'Speeltuinvereniging De Hoogte', 'http://speeltuinengroningen.nl/speeltuinen/bsv-de-hoogte/', 'Speeltuin voor kinderen vanaf dat ze kunnen lopen, en een voetbalkooi voor de grotere kinderen. Veel kinderen zodra het mooi weer is. ', 'Borgwal, Groningen ', 53.2341, 6.56233, 1, 56, 1, 1, 1, 1, 'Toestelspeeltuin', 'speeltuinvereniging-de-hoogte', '2018-03-13 22:34:14', 0, 0, 0, '', ''),
(233, 'Doepark Nooterhof', '', 'Natuurlijk spelen...lekker met water enz... super leuk & groot. Vooral heerlijk in het voorjaar / de zomer.', 'Doepark Nooterhof', 52.5048, 6.11794, 1, 5, 1, 0, 1, 1, 'Natuurspeeltuin', 'doepark-nooterhof', '2018-03-14 14:10:17', 0, 0, 0, '', ''),
(234, 'Kinderboerderij en natuurspeeltuin Hoogezand ', '', 'Bij de kinderboerderij in Hoogezand is een harstikke leuke natuurspeeltuin gecreÃ«erd. Er kan met water gespeeld worden en geklommen in de speeltoestellen. Bovendien zijn er een heleboel leuke ontdekkingspaadjes. ', 'Burgemeester van Royenstraat 11, Hoogezand', 53.157, 6.72951, 1, 5, 1, 0, 1, 1, 'Kinderboerderij met speeltuin', 'kinderboerderij-en-natuurspeeltuin-hoogezand-', '2018-03-14 21:49:04', 0, 0, 0, '', ''),
(235, 'Bosmansweg speeltuin Nieuwleusen ', '', 'Leuke speeltuin op groot grasveld met wip, schommels, glijbaan, draaimolen, pingpongtafel, basketbalveld. ', 'Bosmansweg Nieuwleusen ', 52.5759, 6.27881, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'bosmansweg-speeltuin-nieuwleusen-', '2018-03-14 21:51:24', 0, 0, 0, '', ''),
(237, 'Fort Drakensteijn', '', 'Onwijs spannende speeltoestellen, picknicktafels en ook kinderboerderij \'t Hoefblad vlak nabij.', 'Prinses Beatrixpark, Schiedam', 51.9288, 4.38031, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'fort-drakensteijn', '2018-03-14 21:54:49', 0, 0, 0, '', ''),
(238, 'Speeltuin het Westen', '', 'Speeltuin voor kinderen van 4 tot 14 jaar, gelegen naast kinderboerderij de Bokkensprong', 'Spaanseweg 38, Rotterdam', 51.9169, 4.42871, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'speeltuin-het-westen', '2018-03-14 21:55:52', 0, 0, 0, '', ''),
(239, 'Beleefpad Kethelpoort ', '', 'Langs het beleefpad beleef je echt vanalles! Je loopt langs een heus insectenhotel, je kan onderste boven hangen als een vleermuis, of kruipen door een web, over een evenwichtsbalk lopen, lekker hangen aan de ringen en nog veel meer.', 'De Harreweg, Schiedam', 51.9504, 4.37115, 1, 5, 1, 0, 1, 1, 'Natuurspeeltuin', 'beleefpad-kethelpoort-', '2018-03-14 21:56:51', 0, 0, 0, '', ''),
(240, 'Prins Hendrikstraat', '', 'Kleine speeltuin in woonerf ', 'Prins Hendrikstraat Pijnacker\r\n', 52.0171, 4.43361, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'prins-hendrikstraat', '2018-03-14 21:57:38', 0, 0, 0, '', ''),
(241, 'Assieshof', '', '', 'Fruitlaan, Loppersum\r\n', 53.3306, 6.75217, 1, 57, 1, 1, 1, 1, 'Toestelspeeltuin', 'assieshof', '2018-03-15 08:09:50', 0, 0, 0, '', ''),
(242, 'Speeltuin Kriejoeltje', '', 'Klimrek, wipwap, wipkip, speelboot, glijbaan, nestschommel\r\nDuikelrekken\r\nPicknickbankjes', 'Geraniumstraat 9581GB Musselkanaal', 52.9315, 7.02008, 1, 5, 1, 1, 1, 0, 'Toestelspeeltuin', 'speeltuin-kriejoeltje', '2018-03-15 08:09:09', 0, 0, 0, '', ''),
(243, 'Speeltuin het Speelhoukje', '', 'Glijbaan, schommel, schommel voor peuters\r\nWipwap, speeltoestel', 'Hanne Bruininghstraat 30 9581CL Musselkanaal', 52.9342, 7.01925, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'speeltuin-het-speelhoukje', '2018-03-15 08:07:21', 0, 0, 0, '', ''),
(244, 'Speeltuin berkenveldje Emmer-Compascuum', '', ' voetbalveld, glijbaan, wipwap, speeltoestel', 'Berkenlaan emmer-compascuum', 52.8089, 7.03971, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'speeltuin-berkenveldje-emmer-compascuum', '2018-03-15 08:05:11', 0, 0, 0, '', ''),
(245, 'Stadspark Emmer-Compascuum', '', 'Het is een soort van survivalroute over en langs het water en een vlot over het water  En  je vindt meerdere speeltuintjes als je de route volgt.\r\nSuper leuk voor de kids.', 'Kijlweg 9 7881JD Emmer-Compascuum', 52.8066, 7.02966, 1, 58, 1, 0, 0, 1, 'Natuurspeeltuin', 'stadspark-emmer-compascuum', '2018-03-15 08:10:54', 0, 0, 0, '', ''),
(246, 'Speeltuintje de Driemolenslaan', '', 'Klein speeltuintje in de wijk', 'Driemolensstraat Muntendam', 53.135, 6.87349, 1, 59, 1, 0, 1, 1, 'Toestelspeeltuin', 'speeltuintje-de-driemolenslaan', '2018-03-15 12:38:30', 0, 0, 0, '', ''),
(248, 'Waterspeeltuin Tanthof', 'http://kinderboerderijtanthof.nl', 'Het is een dier- en kindvriendelijke kinderboerderij met (water)speeltuin.', 'Abtswoude 5, Delft', 51.9859, 4.35373, 1, 60, 1, 1, 1, 1, 'Kinderboerderij met speeltuin', 'waterspeeltuin-tanthof', '2018-03-15 20:30:05', 0, 0, 0, '', ''),
(249, 'Nijverheid', '', 'Afgedekte zandbak. Speelhuis met glijbaan (Geen metalen die heet wordt in de zomer). Kabelbaan. Twee bankjes voor de ouders. Genoeg plat groen voor picknickkleden. Wiebelfiguurtjes waar ook de kleintjes in kunnen. Niet piepende schommels, ook een babyschommel. Camera om overlast en vernieling tegen te gaan', 'De Nijverheid, Drachten', 53.1183, 6.08294, 1, 5, 1, 1, 1, 0, 'Toestelspeeltuin', 'nijverheid', '2018-03-16 07:59:38', 0, 0, 0, '', ''),
(250, 'Speeltuin in Etten-Leur vlakbij Slotlaan', '', 'Groot grasveld, grote wip, schommels, 1 glijbaan met tuinhuisje, klein wipje, zandbak, grote glijbaan', 'Etten-Leur, vlakbij Slotlaan', 51.5673, 4.63878, 1, 5, 1, 1, 1, 0, 'Toestelspeeltuin', 'speeltuin-in-etten-leur-vlakbij-slotlaan', '2018-03-16 07:59:09', 0, 0, 0, '', ''),
(251, 'Speeltuin Nederhemert Zuid', '', 'Zeer leuke speeltuin op het eiland Nederhemert Zuid. Heerlijk tussen de bomen en met een mooi buitenterras.', 'Eiland Nederhemert Zuid ', 51.7495, 5.14957, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'speeltuin-nederhemert-zuid', '2018-03-16 08:07:53', 0, 0, 0, '', ''),
(252, 'Thienbunder', '', 'Gezellige speeltuin voor kids tussen de 2 en 12. Lekker klimmen, glijden, schommelen en zelfs met water spelen. ', 'Monseigneur Canoynstraat, Sittard', 50.9946, 5.85453, 1, 5, 1, 0, 1, 0, 'Toestelspeeltuin', 'thienbunder', '2018-03-16 08:10:47', 0, 0, 0, '', ''),
(253, 'Fort Willem', 'http://www.speeltuinfortwillem.nl', 'Leuk voor jonge en oudere kinderen. In de zomer een leuk buitenzwembad. Kunt er een lekker frietje eten en op het terras zitten', 'Kastanjelaan 50, 6217 SB Maastricht', 50.8578, 5.67737, 1, 62, 2, 1, 1, 1, 'Toestelspeeltuin', 'fort-willem', '2018-03-16 08:14:09', 0, 0, 0, 'Zaterdag 1 april 2017 om 10.00!\r\nMaandag t/m zaterdag 10.00 -18.00 en op zondag van 11.00 - 18.00u t/m zaterdag 30 september 2017.Â \r\n\r\nÂ \r\n\r\n', '2 euro pp'),
(254, 'Speeltuin Heer', 'https://speeltuinheer.wordpress.com', 'Leuke gratis speeltuin. Goed onderhouden door vrijwilligers. Toiletten aanwezig. Er kunnen snacks en drinken gekocht worden', 'Speeltuin Heer, Akersteenweg, Maastricht', 50.8434, 5.73054, 1, 62, 1, 0, 1, 1, 'Toestelspeeltuin', 'speeltuin-heer', '2018-03-16 08:19:14', 0, 0, 0, 'Maandag t/m vrijdag van 11.00u - 17.00u. \r\nZaterdag en zondag van 11.00u - 17.00u. \r\nIn het weekend zijn we alleen open als er een vrijwilliger is!', ''),
(255, 'De Dwaze Herder', 'http://www.dwazeherder.nl', 'Restaurant, terras, speeltuin, dieren en in de winter een ijsbaan', 'De Dwaze Herder, direct langs de A2 bij Maastricht (afslag Gronsveld)', 50.816, 5.72542, 1, 62, 1, 1, 1, 1, 'Kinderboerderij met speeltuin', 'de-dwaze-herder', '2018-03-16 08:19:15', 0, 0, 0, '', ''),
(256, 'Speeltuinvereniging Hulhuizen', '', 'Een schitterende grote speeltuin. Met schommels, glijbanen, zandbak maar ook een skelterbaan en nog veel meer...', 'Munnikhofsestraat 22a, Gendt', 51.8798, 5.99228, 1, 5, 2, 1, 1, 1, 'Toestelspeeltuin', 'speeltuinvereniging-hulhuizen', '2018-03-16 09:06:55', 0, 0, 0, '', 'Je betaalt wel een kleine vergoeding om er te mogen spelen. Maar je kunt ook een lidmaatschap nemen voor het hele gezin'),
(257, 'Speeltuin de Speelboom in Herwijnen ', '', 'Leuke speeltuin met veel toestellen. Er staan schommels, klimtoestellen, speelhuisje met glijbaan, wipwap, wipkip, voetbaldoeltjes, draaischijf, vogelnest. ', 'Herwijnen ', 51.8273, 5.12815, 1, 5, 1, 1, 1, 0, 'Toestelspeeltuin', 'speeltuin-de-speelboom-in-herwijnen-', '2018-03-16 11:54:17', 0, 0, 0, '', ''),
(258, 'Speeltuintje Elzenplantsoen Sittard', '', 'Kleine speeltuin, vrij toegankelijk. Met wip, draaimolen en klimtoestel met glijbaan', 'Elzenplantsoen Sittard', 50.9922, 5.86026, 1, 5, 1, 1, 1, 0, 'Toestelspeeltuin', 'speeltuintje-elzenplantsoen-sittard', '2018-03-16 13:38:00', 0, 0, 0, '', ''),
(260, 'Het Goudenwoud', '', 'Een binnenspeeltuin.\r\nAlles is in het zand met beekje en waterpompen. De kinderen kunnen op zoek naar goud en krijgen wat leuks als ze het gevonden goud inleveren.', 'Hamsestraat 18 Liempde', 51.5578, 5.37761, 1, 5, 1, 0, 1, 1, 'Natuurspeeltuin', 'het-goudenwoud', '2018-03-16 13:43:29', 0, 0, 0, '', ''),
(262, 'Natuurspeeltuin Batadorp', '', 'In de wijk Batadorp in Best ligt een super leuke natuurspeeltuin voor jong en oud! Mogelijkheid tot klimmen klauteren, sporten en spelen met zand en water', 'Zwikkerstraat, Best', 51.4905, 5.39806, 1, 5, 1, 0, 1, 1, 'Natuurspeeltuin', 'natuurspeeltuin-batadorp', '2018-03-16 14:59:57', 0, 0, 0, '', ''),
(263, 'Natuurspeeltuin in Waspik', '', 'De natuurspeeltuin wordt op zaterdagmiddag 14 april geopend.  De officiele naam wordt dan ook bekend gemaakt. Maar het belooft een mooie natuurspeeltuin te worden.', 'Irenestraat Waspik', 51.6849, 4.94386, 1, 5, 1, 1, 1, 1, 'Natuurspeeltuin', 'natuurspeeltuin-in-waspik', '2018-03-16 16:42:58', 0, 0, 0, '', ''),
(264, 'Bosspark Sittard', '', 'Leuke en gezellige speel-/sporttuin.\r\nBOSS staat voor, Bewegen-Ontmoeten-Sport en Spel. \r\nOp het BOSS zijn verschillende sport- en beweegfaciliteiten, zoals een Johan Cruijff Court, een interactief Marc Lammers plaza, een multifunctioneel basketbalveldje, een BMX-parcours en buitenfitnessaparaten. Daarnaast vinden er wekelijks vele activiteiten plaats voor verschillende doelgroepen. Neem een kijkje op de website van het BOSS voor meer informatie en een overzicht van de wekelijkse activiteiten.', 'Bachstraat 51 Sittard ', 50.9991, 5.88958, 1, 63, 1, 0, 1, 1, 'Sportfaciliteit', 'bosspark-sittard', '2018-03-16 20:55:19', 0, 0, 0, '', ''),
(265, 'Sjoepienoe Sittard ', '', 'Nieuwe grote buitenspeeltuin met hele leuke speeltoestellen. ', 'Jan Steenstraat 1a Sittard', 51.0062, 5.88893, 1, 63, 1, 0, 1, 1, 'Toestelspeeltuin', 'sjoepienoe-sittard-', '2018-03-16 20:57:07', 0, 0, 0, '', ''),
(266, 'Stadsspeelbos Sjabolleke Sittard', '', 'Laat je fantasie de vrije loop en ga lekker spelen in stadsspeelbos Sjabolleke! Aan de Molenweg, pal naast het monumentale stadspark van Sittard en middenin het beekdal, vind je een avontuurlijk stuk bos. Klim in bomen, bouw hutten, banjer door de struiken en spring over slootjes. Er zijn een aantal speelvoorzieningen, maar het is toch veel leuker om het water te overwinnen en een mooie dam te bouwen? Sjabolleke is een openbaar toegankelijke natuurspeeltuin.', 'Molenweg 6133 Sittard', 50.9881, 5.86141, 1, 63, 1, 1, 1, 1, 'Natuurspeeltuin', 'stadsspeelbos-sjabolleke-sittard', '2018-03-16 20:56:36', 0, 0, 0, '', ''),
(267, '\'t Kwekkeltje', 'https://kwekkeltje.wordpress.com/', 'Speeltuin met veel ruimte om als ouders ook lekker op het gras te zitten of op een bankje. De speeltuin is al leuk vanaf dat de kinderen kruipen en door de verschillende activiteiten blijft het ook lang leuk! Kliederen met water kan hier ook heerlijk.', 'Sportlaan, Rosmalen', 51.7122, 5.36605, 1, 5, 2, 1, 1, 1, 'Toestelspeeltuin', 't-kwekkeltje', '2018-03-16 20:49:21', 0, 0, 0, 'Kijk op de site voor de openingstijden.', ''),
(268, 'De Gerrithoeve', '', 'Een leuke buitenspeeltuin met een fijn terras! ', 'Gerrithoeve, Oisterwijk', 51.5423, 5.24456, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'de-gerrithoeve', '2018-03-16 20:45:39', 0, 0, 0, '', ''),
(270, 'Speeltuin de Zoemer', '', '', 'Talingweg 84, Apeldoorn', 52.1996, 5.96839, 1, 64, 2, 1, 1, 1, 'Toestelspeeltuin', 'speeltuin-de-zoemer', '2018-03-17 21:12:50', 0, 0, 0, 'Maandag 15:00 - 17:00\r\nDinsdag 15:00 - 17:00\r\nWoensdag 14:00 - 17:00\r\nDonderdag 15:00 - 17:00\r\nVrijdag 14:00 - 17:00\r\nZaterdag 14:00 - 17:00\r\nZondag 14:00 - 17:00', ''),
(272, 'Buurtspeeltuin Loppersum', '', '', 'Zorgvlijt, Loppersum\r\n', 53.3318, 6.75506, 1, 57, 1, 1, 1, 1, 'Toestelspeeltuin', 'buurtspeeltuin-loppersum', '2018-03-18 10:04:29', 0, 0, 0, '', ''),
(273, 'Buurtspeeltuin Middelstum ', '', 'Dit is een hofje maar de speeltuin zit in de hoek van het allerlaatste blok ', '2e Bentensdwarsweg', 53.347, 6.63699, 1, 57, 1, 1, 1, 1, 'Toestelspeeltuin', 'buurtspeeltuin-middelstum-', '2018-03-18 10:06:40', 0, 0, 0, '', ''),
(274, 'Buurtspeeltuin Stedum', '', '', 'Vlaspad, Stedum\r\n\r\n', 53.3229, 6.6983, 1, 57, 1, 1, 1, 1, 'Toestelspeeltuin', 'buurtspeeltuin-stedum', '2018-03-18 10:14:39', 0, 0, 0, '', ''),
(276, 'Buurtspeeltuin Laagstraat, Rijen', '', '', 'Laagstraat, Rijen', 51.5901, 4.92577, 1, 65, 1, 0, 1, 0, 'Toestelspeeltuin', 'buurtspeeltuin-laagstraat-rijen', '2018-03-18 10:16:45', 0, 0, 0, '', ''),
(277, 'Speeltuin kabelbaan', '', '', 'Laagstraat, Rijen', 51.5946, 4.92603, 1, 65, 1, 1, 1, 1, 'Toestelspeeltuin', 'speeltuin-kabelbaan', '2018-03-18 08:04:15', 0, 0, 0, '', ''),
(278, 'Speeltuin bij de Visvijvers', '', '', 'Wolfsweide, Visvijvers, Rijen ', 51.5992, 4.92444, 1, 65, 1, 1, 1, 1, 'Toestelspeeltuin', 'speeltuin-bij-de-visvijvers', '2018-03-18 10:17:30', 0, 0, 0, '', ''),
(280, 'Wandelbos Tilburg', '', 'Speelgedeelte, boederij, ijsjes, parkeergelegenheid ', 'Wandelbos, Tilburg', 51.5706, 5.04342, 1, 66, 1, 1, 1, 1, 'Natuurspeeltuin', 'wandelbos-tilburg', '2018-03-19 09:43:52', 0, 0, 0, '', ''),
(281, 'Speelpark de Splinter', 'https://www.speelparkdesplinter.nl/', 'Superleuk speelpark voor de kids met veel voorzieningen zoals een peutergedeelte, piratengedeelte,\r\nkabelbaan, kinderboerderij, zwembad, hutten bouw gedeelte etc. Ze organiseren ook veel extra dingen voor de\r\nkids tussendoor en het beste? de toegang is gratis van maandag tot en met zaterdag, alleen op zondag betaal je 1.50 entree.\r\nHet is een schoon goed onderhouden park met veel picknicktafels en zelfs een kleine kiosk.\r\n', 'Rode Kruislaan, Eindhoven ', 51.477, 5.4714, 1, 67, 2, 1, 1, 1, 'Kinderboerderij met speeltuin', 'speelpark-de-splinter', '2018-03-18 13:49:39', 0, 0, 0, '', 'De toegang is gratis van maandag tot en met zaterdag, alleen op zondag betaal je 1.50 entree.'),
(282, 'Somerweide', '', 'Gratis speeltuin met ruimte voor zo\'n 200 kinderen waar je gezellig een dag kunt vertoeven.', 'Somerweide, Breda', 51.6116, 4.74651, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'somerweide', '2018-03-18 13:51:51', 0, 0, 0, '', ''),
(283, 'Speelbos De Kemmer ', 'http://www.speelbosdekemmer.nl/', 'Leuk bos waar ze houten dieren gemaakt hebben die door het hele bos verspreid staan en je als speurtocht kan gaan zoeken. Je kan er klimmen, hutten bouwen en van de natuur genieten.', 'De Kemmer 1, Oirschot ', 51.4949, 5.31448, 1, 67, 1, 1, 1, 0, 'Natuurspeeltuin', 'speelbos-de-kemmer-', '2018-03-18 13:50:45', 0, 0, 0, '', ''),
(284, 'Ericaschool in Otterlo', '', '', 'Kerklaan 1', 52.3497, 4.62099, 1, 5, 1, 0, 1, 0, 'Toestelspeeltuin', 'ericaschool-in-otterlo', '2018-03-18 14:28:40', 0, 0, 0, '', ''),
(285, 'Speeltuin Lewedorp', '', '', 'School Leeuwerik te Lewedorp', 51.4965, 3.75171, 1, 68, 1, 1, 1, 1, 'Toestelspeeltuin', 'speeltuin-lewedorp', '2018-03-18 13:58:51', 0, 0, 0, '', ''),
(286, 'Bouwspeelplaats De Leuke Linde', '', 'Water, zand en klimmen!', 'Onder de Linden 2, Arnhem', 51.9892, 5.91667, 1, 5, 1, 0, 1, 1, 'Natuurspeeltuin', 'bouwspeelplaats-de-leuke-linde', '2018-03-18 20:58:53', 0, 0, 0, '', ''),
(287, 'Speeltuin de Viking', '', 'Speeltuin de Viking is de oudste en de grootste speeltuin in de gemeente Geldropâ€“Mierlo. Bijzonder aan de speeltuin is dat er een aantal exotische bomen staat waardoor er volop schaduw is, maar er is toch ook voldoende plek om te zonnen.\r\nZe bieden bijnaÂ 6.000 m2 speelplezier, met 17 grote speeltoestellen en 28 kleinere. Er is een aparte peuterhoek.\r\nVoor de ouders hebben ze een groot aantal picknicktafels met parasols. Er is een winkeltje waar koffie, thee, ranja, ijs, snoep, chips, blikjes frisdrank en worstenbroodjes en tostiâ€™s kunnen worden gekocht. Er kan worden gepind.\r\nDe Viking is een openluchtspeeltuin, bij heel slecht weer zijn ze gesloten. Indien van toepassing wordt dit aangegeven op hun site en ook op Facebook.\r\nDe speeltuin beschikt over een invalidentoilet. Honden zijn niet toegestaan.\r\n\r\n', 'Speeltuinpad, Geldrop', 51.4252, 5.5668, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'speeltuin-de-viking', '2018-03-19 09:16:47', 0, 0, 0, '', ''),
(289, 'Speeltuin Korenmaat', 'https://www.facebook.com/stadsboerderijdekorenmaat/', 'Grote kinderboerderij met grote speeltuin en kabelbaan. Vaak activiteiten te doen.', 'Stadboerderij de Korenmaat', 51.9469, 5.90036, 1, 69, 1, 1, 1, 1, 'Kinderboerderij met speeltuin', 'speeltuin-korenmaat', '2018-03-19 10:14:26', 0, 0, 0, '', ''),
(290, 'Speeltuin Gestel', 'http://speeltuingestel.nl/over-de-speeltuin/wat-je-moet-weten/', 'Heerlijk spelen en lekker vies worden', 'Meanderplein 1, Sint-Michielsgestel', 51.64, 5.34786, 1, 69, 1, 1, 1, 1, 'Natuurspeeltuin', 'speeltuin-gestel', '2018-03-19 10:16:35', 0, 0, 0, '', ''),
(292, 'Karen Weening Speeltuin', '', 'Hele grote speeltuin met een bosgevoel', 'Lavendelweg Tilburg', 51.5783, 5.04596, 1, 60, 1, 1, 1, 1, 'Natuurspeeltuin', 'karen-weening-speeltuin', '2018-03-19 10:48:31', 0, 0, 0, '', ''),
(293, 'Speelweide Stakenberg', '', 'Speelweide Stakenberg is een natuurspeeltuin met ook een aantal speeltoestellen. Je kunt er heerlijk picknicken, voetballen, van de kabelbaan of de klimtoren beklimmen. Ook kun je er boomhutten bouwen.', 'Stakenbergweg, Elspeet', 52.3099, 5.74903, 1, 70, 1, 1, 1, 1, 'Natuurspeeltuin', 'speelweide-stakenberg', '2018-03-19 10:50:13', 0, 0, 0, '', ''),
(294, 'Speeltuin Terveurdt', '', 'Superleuke speeltuin gelegen in het zuiden.', 'Professor Koopmansstraat 2A, 6431 WB Hoensbroek\r\n\r\n', 50.9204, 5.93739, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'speeltuin-terveurdt', '2018-03-19 10:51:33', 0, 0, 0, '', ''),
(295, 'Kinderboerderij Geldrop', 'http://www.kinderboerderijgeldrop.nl/', 'Superleuke kinderboerderij waar je zelfs de geitjes en schapen eten kan geven. Kost 30 cent en je kan ook een strippenkaart voor voer halen.\r\nDe toegang is altijd gratis.\r\nEr zijn knuffeltijden voor de konijntjes en ze hebben veel dieren. Cavia\'s, muizen, katten, konijnen, ezels, varkens, zelfs kalkoenen etc. ', 'Mierloseweg, Geldrop', 51.424, 5.55866, 1, 67, 1, 1, 1, 1, 'Kinderboerderij', 'kinderboerderij-geldrop', '2018-03-19 13:03:43', 0, 0, 0, '', ''),
(296, 'Speeltuin \'t Hingen', '', 'Speeltuin vanaf dat ze kunnen lopen t/m basisschoolleeftijd. Voor kleine kinderen zijn glijbaan, huisje, draaitoestellen, wip en schommels apart.\r\nVerder waterspeeltafels, klimtoestellen, kabelbaantje, schommels en o.a. hoog klimtoestel met glijbanen.\r\nIn de hele speeltuin ligt zand. Er zijn een paar bankjes in speeltuin en vooraan tafels met banken om bijv. te picknicken of voor ouders tijdens het wachten.', 'Hoogveldsweg, Pey-Echt, gemeente Echt-Susteren', 51.1015, 5.89248, 1, 5, 2, 1, 1, 0, 'Toestelspeeltuin', 'speeltuin-t-hingen', '2018-03-19 13:37:26', 0, 0, 0, 'Hele seizoen geopend tot zonsondergang.', ''),
(298, 'Speelkoel ', '', 'Deze speeltuin heeft een apart gedeelte voor kleinere en grotere kinderen. In het middenstuk is een terras. Ook is er een winkeltje voor snoepgoed, drinken en ijs. Het grote gedeelte heeft o.a. en grote glijbaan vanuit een houten toren, een groot klimtoestel, familieschommel, waterspeeltafel en evenwichtstoestellen. Hier ligt vooral overal zand. \r\nBij de kleintjes is er veel gras. Er is en huisje, schommels, wippen en een klimhuis met bruggen en zandscheptakelbakjes. Bij het terras is een fonteinpleintje met een paar andere waterspeeltoestellen.', 'Kievitstraat, Sint Joost', 51.1154, 5.89781, 1, 5, 1, 1, 1, 1, 'Toestelspeeltuin', 'speelkoel-', '2018-03-19 13:41:32', 0, 0, 0, '', ''),
(299, 'Oerrr Speeltuin Hompesche Molen', '', 'Dit is geen traditionele speeltuin met toestellen. Alles hier is van hout en zoveel mogelijk natuurlijke materialen. Er is een pomp wat je water kunt pompen. Omdat het hier omlaag loopt kun je met aanwezige zand en stenen zelf dijkjes maken en bepalen waar het water naartoe stroomt. Verder zijn er bruggen en kronkelende paden,  een eilandje te bereiken via stapstenen en huisjes van gevlochten takken en hout. Er zijn fruitbomen waar je een stuk fruit mag plukken (juiste tijd van het jaar uiteraard).', 'Molendijk, Stevensweert', 51.1205, 5.83707, 1, 5, 1, 0, 1, 1, 'Natuurspeeltuin', 'oerrr-speeltuin-hompesche-molen', '2018-03-19 13:42:45', 0, 0, 0, '', ''),
(300, 'Kinderboerderij Zandberg', '', 'Kleine kinderboerderij met groot grasveld en speeltuin.', 'Marijke Meustraat, Breda (achter Muzipo)', 51.574, 4.77892, 1, 71, 1, 1, 1, 0, 'Kinderboerderij met speeltuin', 'kinderboerderij-zandberg', '2018-03-19 14:54:16', 0, 0, 0, '', ''),
(301, 'Dorus Rijkersstraat', '', 'Het speeltuintje bestaat uit 2 delen, een toestelspeeltuin en een voetbalveldje met 2 doelen.', 'Dorus Rijkersstraat, Amersfoort', 52.1825, 5.40908, 1, 21, 1, 0, 1, 1, 'Toestelspeeltuin', 'dorus-rijkersstraat', '2018-03-20 22:39:21', 0, 0, 0, '', ''),
(302, 'Park de Horst', 'https://www.denhaag.nl/nl/in-de-stad/stadsdelen/haagse-hout/herinrichting-wijkpark-de-horst.htm', 'Zelf speelde ik hier al vroeger. Toen was er ook nog een kinderboerderij, die is helaas nu weg. Ze zijn dit park nu ook aan het herinrichten en het wordt zo mooi. Staat nu al een heel mooi groot speeltoestel. Ik vind het geweldig om te zien dat mijn zoontje net zo gek is op dit park als ik op die leeftijd. ', 'Park de Horst, 2592 HB, Den Haag', 52.093, 4.35932, 1, 72, 1, 1, 1, 1, 'Toestelspeeltuin', 'park-de-horst', '2018-03-21 12:07:16', 0, 0, 0, '', ''),
(303, 'Minispeeltuin Grutto', '', 'Klein speeltuintje omringd door groot grasveld.', 'Grutto, Groningen', 53.1799, 6.54142, 1, 5, 1, 1, 1, 0, 'Toestelspeeltuin', 'minispeeltuin-grutto', '2018-03-23 09:38:16', 0, 0, 0, '', ''),
(304, 'Ruimtewandelen in het park', 'http://ruimtewandeleninhetpark.nl/', 'Je wandelt door het park en kijkt via je tablet of smartphone om je heen, kijk ook tussendoor omhoog de lucht in en ontdek zelfs daar astronauten, raketten, maanlanders en planeten.', 'Alberdingk Thijmlaan 3, Eindhoven', 51.4261, 5.48005, 1, 67, 1, 1, 1, 0, 'Natuurspeeltuin', 'ruimtewandelen-in-het-park', '2018-03-26 10:36:39', 0, 0, 0, '', ''),
(305, 'Heempark ', 'https://www.dse.nl/~heempark-ehv/', 'Leuke en leerzame ontdekkings wandeltocht in het Heempark, gelegen in de Genneper parken.\r\nVerschillende Brabantse mini-landschappen trekken aan je voorbij. Je kan er van alles zien, kikkers, paddenstoelen in de herfst, mooie bloemen, kevers etc. Er is zelfs water. Je kan ook tussendoor een pauze nemen en op houten blokken een hapje eten voordat je weer verder gaat. De entree is altijd gratis.', 'Genneperweg 145, Eindhoven', 51.4231, 5.4707, 1, 67, 1, 1, 1, 1, 'Natuurspeeltuin', 'heempark-', '2018-03-26 10:37:24', 0, 0, 0, '', ''),
(306, 'WSV de Hoven', '', 'Leuke speeltuin, groot 3000 m2, urenlang plezier voor groot en klein!\r\nGratis toegankelijk, toezicht en een horecapunt met betaalbare prijzen', 'Leliestraat 27 Deventer', 52.2492, 6.1397, 1, 5, 1, 1, 1, 1, 'Toestelspeeltuin', 'wsv-de-hoven', '2018-03-28 08:51:48', 0, 0, 0, '', ''),
(307, 'Woeste Willem', '', 'Een leuke speelplek waar kinderen zich echt kunnen uitleven in een natuurlijke speeltuin.', 'Bolwerksweg, De Worp (gemeente Deventer)', 52.2525, 6.14876, 1, 5, 1, 1, 1, 1, 'Natuurspeeltuin', 'woeste-willem', '2018-03-28 08:58:22', 0, 0, 0, '', ''),
(308, 'De Driehoek', '', 'Erg mooie speeltuin, veilige toestellen en goed onderhouden! Gegarandeerd urenlang speelplezier voor kinderen.', 'Rielerweg 110 Deventer', 52.2581, 6.1724, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'de-driehoek', '2018-03-28 08:59:17', 0, 0, 0, '', ''),
(309, 'Speeltuin Emmer-Compascuum', '', 'Klimrek en voetbalveld', 'Tweede Koppelveenweg, Emmer-Compascuum ', 52.8134, 7.05695, 1, 58, 1, 0, 1, 1, 'Toestelspeeltuin', 'speeltuin-emmer-compascuum', '2018-03-28 09:01:35', 0, 0, 0, '', ''),
(310, 'Speeltuin Huls', '', 'Speeltuin met schommel en speelhuisje met glijbaan', 'Huls, Emmer-Compascuum ', 52.8139, 7.04559, 1, 58, 1, 1, 1, 1, 'Toestelspeeltuin', 'speeltuin-huls', '2018-03-28 09:31:17', 0, 0, 0, '', ''),
(311, 'Speeltuin Acacialaan', '', 'Schommel, glijbaan en speeltoestel', 'Acacialaan 67, Emmer-Compascuum ', 52.8082, 7.03676, 1, 58, 1, 0, 1, 1, 'Toestelspeeltuin', 'speeltuin-acacialaan', '2018-03-28 09:32:04', 0, 0, 0, '', ''),
(313, 'speeltuin noordwesterhoek', 'https://www.facebook.com/speeltuin.sneek/', 'Een leuke speeltuin met leuke vrijwilligers. Ook is het mogelijk om met ander speelgoed te spelen, en komt er nog een groter toestel voor de wat oudere kinderen', 'Doctor Kuyperlaan 3A, Sneek', 53.0396, 5.6621, 1, 73, 2, 1, 1, 1, 'Toestelspeeltuin', 'speeltuin-noordwesterhoek', '2018-03-28 08:50:51', 0, 0, 0, 'vanaf 31 maart van maandag tot vrijdag van 13:00 tot 17:00', 'er zijn consumpties te koop tegen een kleine vergoeding'),
(314, 'Kinderboerderij Sneek', 'http://www.kinderboerderijsneek.nl/', 'leuke kinderboerderij met speeltuin', 'Harste, Sneek', 53.0374, 5.64815, 1, 73, 2, 1, 1, 1, 'Kinderboerderij met speeltuin', 'kinderboerderij-sneek', '2018-03-28 09:00:43', 0, 0, 0, 'open van dinsdag t/m zondag van 13:00 tot 17:00 ', 'entree is vanaf 2 jaar 2 euro p.p'),
(315, 'Speeltuin Sperkhem Tuindorp', 'https://www.facebook.com/SpeeltuinverenigingSperkhemTuindorp/', 'Speeltuin in Sperkhem', 'Jan van Nassaustraat 21A, sneek', 53.0299, 5.66687, 1, 73, 2, 1, 1, 1, 'Toestelspeeltuin', 'speeltuin-sperkhem-tuindorp', '2018-03-28 09:30:38', 0, 0, 0, 'van maandag t/m vrijdag van 14:00 tot 17:00 uur', '2 euro entree'),
(316, 'Buurtspeeltuin Geert Teisstraat in Veendam', '', 'Er staat jammer genoeg nog maar 1 schommel', 'Geert Teisstraat, Veendam ', 53.1162, 6.88528, 1, 5, 1, 0, 1, 0, 'Toestelspeeltuin', 'buurtspeeltuin-geert-teisstraat-in-veendam', '2018-03-31 10:49:51', 0, 0, 0, '', ''),
(317, 'Speeltuin Braamstraat', '', 'Kleine speeltuin in groene omgeving met speeltrein, schommels, glijbaan, zandbak en klimrek', 'Braamstraat, Groningen', 53.2311, 6.60502, 1, 33, 1, 0, 1, 1, 'Toestelspeeltuin', 'speeltuin-braamstraat', '2018-04-05 12:13:52', 0, 0, 0, '', ''),
(318, 'Speeltuin Lavendelweg', '', 'Speeltuintje met glijbaan en wipkip', 'Lavendelweg 25, Groningen', 53.2354, 6.59802, 1, 33, 1, 0, 1, 1, 'Toestelspeeltuin', 'speeltuin-lavendelweg', '2018-04-05 12:17:45', 0, 0, 0, '', ''),
(319, 'Speeltuin Wethouder vd Berglaan', '', 'Speeltuin in Nieuwleusen', 'Wethouder van den Berglaan, Nieuwleusen', 52.5744, 6.29521, 1, 18, 1, 0, 1, 1, 'Toestelspeeltuin', 'speeltuin-wethouder-vd-berglaan', '2018-04-08 21:12:55', 0, 0, 0, '', ''),
(320, 'Buurtspeeltuintje Reint Dijkemastraat', '', 'Klein buurtspeeltuintje met schommels, een klimrek, een glijbaan en een wipwap.', 'Reint Dijkemastraat Siddeburen', 53.2446, 6.87069, 1, 42, 1, 0, 1, 0, 'Toestelspeeltuin', 'buurtspeeltuintje-reint-dijkemastraat', '2018-05-02 14:42:09', 0, 0, 0, '', ''),
(321, 'Mainstraat', '', 'Evenwichtsbalk en rekstok', 'Mainstraat', 53.012, 6.54535, 1, 21, 1, 0, 1, 1, 'Toestelspeeltuin', 'mainstraat', '2018-05-07 08:30:58', 0, 0, 0, '', ''),
(322, 'Papayapad-Frambozenhof', '', '2 toestellen. Een glijbaanhuisje en een klimtoestel met schommel. Beide op rubbertegels met rondom gras.', 'Frambozenhof', 53.0031, 6.51502, 1, 21, 1, 1, 1, 0, 'Toestelspeeltuin', 'papayapad-frambozenhof', '2018-06-30 11:23:27', 0, 0, 0, '', ''),
(323, 'Wildpark an den Eichen', 'https://wildparkfreunde-schweinfurt.de/der-wildpark/', 'Een fantastisch (gratis toegankelijk) park. Een dierentuin met dieren zoals: herten, elanden, lynchen, uilen, hooglanders, vogels, konijnen, cavia\'s ganzen, varkens, geiten en bokken. De geitjes kun je aaien. In het midden is een klein \'bad\' met fonteinen en tunnels voor zomerse waterpret met grote speeltuinen met vanalles. \r\nVan nestschommels tot grote klimtoestellen.\r\nTegen betaling kun je midgetgolfen of gebruik maken van de horeca. \r\nParkeren is ook gratis.', 'Schweinfurt, Duitsland', 50.0644, 10.2458, 1, 21, 1, 1, 1, 1, 'Kinderboerderij met speeltuin', 'wildpark-an-den-eichen', '2018-08-24 07:29:17', 0, 0, 0, '', ''),
(324, 'Speeltuin De Speelschans', '', 'De Speelschans ligt prachtig groen gelegen middenin het Roomburgerpark (ingang vanuit Van Vollenhovenkade of Kanaalweg). Door de omringende bomen en de met gras begroeide â€˜schansâ€™ en heuvel in het park is het er heerlijk toeven voor zowel kinderen als ouders. De speeltuin bevat onder andere een klimkasteel, een touwenklimrek, een waterspeelplaats met pomp, een apart gedeelte voor peuters. Oudere kinderen kunnen rondrijden op een van onze skelters en een potje tafeltennissen. De speeltuin is ook toegankelijk voor rolstoelgebruikers.\r\n\r\nDe Speelschans is een open speeltuin. Dit betekent dat iedereen gratis toegang heeft tot de speeltuin. Je hoeft dus geen entreegeld te betalen of lid te zijn van de speeltuinvereniging om met de kinderen te komen spelen. Afgezien van de wintermaanden is er elke werkdag van 11 tot 17 uur een portier aanwezig die drinken, snoep, chips en ijs verkoopt en ervoor zorgt dat de toiletten open zijn.', 'Van Vollenhovenkade, Leiden', 52.1482, 4.50527, 1, 5, 1, 1, 1, 1, 'Toestelspeeltuin', 'speeltuin-de-speelschans', '2018-09-04 08:23:59', 0, 0, 0, '', '');
INSERT INTO `speeltuin` (`id`, `naam`, `link`, `omschrijving`, `locatie_omschrijving`, `lat`, `lon`, `status_id`, `author_id`, `public`, `agecat_1`, `agecat_2`, `agecat_3`, `speeltuintype`, `seo_url`, `modified_on`, `total_rating`, `times_rated`, `avg_rating`, `openingstijden`, `vergoeding`) VALUES
(325, 'Speeltuin Kloosterplantsoen', 'http://www.speeltuinkloosterplantsoen.nl ', 'De speeltuin Kloosterplantsoen is een vrij toegankelijke speeltuin gelegen net buiten het historische stadje IJsselstein. Hij is gelegen op de oude fundamenten van een klooster. De speeltuin heeft de goedkeuring van de NSGK en is daardoor ook geschikt voor kinderen met een beperking. Als zelfstandige stichting bezitten we een paviljoen waarbij wij streven met vrijwilligers iedere middag open te zijn bij goed weer. Bij opening kunt u beschikken over een (invalide) toilet. We zetten speelgoed buiten en er is naast een droge ook een waterzandbak. Verder meerdere toestellen en klimmogelijkheden voor de kinderen', 'Anna van Burenpad 1 IJsselstein (u)', 52.0189, 5.04818, 1, 78, 1, 1, 1, 1, 'Toestelspeeltuin', 'speeltuin-kloosterplantsoen', '2018-09-14 21:35:11', 0, 0, 0, '', ''),
(326, 'Kinderboerderij Roden', 'http://volksvermaken.nl/kinderboerderij', 'Aan de Norgerweg 2 in Roden vindt u een schitterende kinderboerderij waar jong en oud zich uitstekend kunnen vermaken. De kinderboerderij, die onder de vlag van de Vereniging voor Volksvermaken Roden valt, vindt u vele verschillende soorten dieren, een theeschenkerij en een speeltuin.', 'Norgerweg 2, Roden', 53.1314, 6.43214, 1, 5, 2, 1, 1, 1, 'Kinderboerderij met speeltuin', 'kinderboerderij-roden', '2018-09-17 08:15:58', 0, 0, 0, 'Zomermaanden (van 1 april tot 1 oktober):\r\nMaandag t/m vrijdag van 09.00 tot 16.45 uur\r\nZaterdag & zondag van 10.00 tot 16.45 uur\r\n\r\nWintermaanden:\r\nMaandag t/m vrijdag van 08.30 tot 15.45 uur\r\nZaterdag & zondag van 11.00 tot 15.45 uur', 'Voor een klein bedrag per jaar helpt u ook mee om deze fraaie kinderboerderij in stand te houden. Word donateur voor slechts â‚¬ 10,- per jaar.'),
(327, 'Lampe\'s Veentie', '', 'Ruim opgezette speeltuin met toestellen en stapstenen. Er is een wip, vogelnestschommel en een kabelbaan maar ook een waterpomp, wadi en insectenhotel. Leuke combinatie van toestellen en \'klimbos\'. Vroeger was er een rolschaatsbaan, maar het asfalt is nu erg versleten. Wat Google Maps voor weg aanziet is eigenlijk het kampje en de rolschaatsbaan, daar rijden geen auto\'s. ', 'Klimopstraat/Bremstraat Norg', 53.064, 6.45448, 1, 42, 1, 1, 1, 0, 'Natuurspeeltuin', 'lampes-veentie', '2018-12-25 15:21:44', 0, 0, 0, '', ''),
(328, 'De Speulkoel', '', 'Wat verscholen in een zijstraatje van de Tilweg ligt een erg ruim opgezette speeltuin. Naast een voetbalveldje vind je er ook een vrij nieuw klimtoestel en wat oudere speeltoestellen. Een aangename en onverwachte verrassing in het rustige Gees!', 'Gees (Dr.), hoek Tilweg en De Brinkies (via â€˜Eigen wegâ€™)', 52.7504, 6.68823, 1, 10, 1, 1, 1, 0, 'Toestelspeeltuin', 'de-speulkoel', '2019-01-01 01:30:57', 0, 0, 0, '', ''),
(329, 'Natuurspeeltuin Peize', '', 'Prachtige, overzichtelijke natuurlijke speeltuin in het groen met naastgelegen hoptuin.', 'Noordsepad Peize', 53.1514, 6.49418, 1, 5, 1, 0, 1, 1, 'Toestelspeeltuin', 'natuurspeeltuin-peize', '2020-07-22 21:03:52', 0, 0, 0, '', ''),
(330, 'Speeltuin de Regenboog ', '', '', 'Beatrixstraat 21A, 9974 RW Zoutkamp', 53.3406, 6.30699, 0, 80, 1, 0, 1, 1, 'Toestelspeeltuin', 'speeltuin-de-regenboog--1', '2024-12-24 21:50:38', 0, 0, 0, '', ''),
(331, 'Molenplas ', '', '3 speeltuinen in het park, een zandbak en een strandje met een zwemmeer', 'Waertmolenpad 1 Haarlem', 52.3459, 4.65523, 0, 81, 1, 1, 1, 1, 'Toestelspeeltuin', 'molenplas-', '2025-02-03 07:15:02', 0, 0, 0, '', ''),
(332, '* * * Claim Free iPhone 16: http://swihartindustries.com/uploaded/jsrqp1.php?s5gji * * * hs=5b556645da46b2aa12505b42c48a1d7b*', '', '24ttw4', '8rqb7d', 0, 0, 0, 5, 1, 0, 1, 1, 'Toestelspeeltuin', '---claim-free-iphone-16-httpswihartindustriescomuploadedjsrqp1phps5gji----hs5b556645da46b2aa12505b42c48a1d7b', '2025-03-15 11:03:33', 0, 0, 0, '', ''),
